window.MONSTER_CHUNK_94 = [{"name":"Bythos","cr":16,"xp":76800,"alignment":"N","size":"Large","type":"outsider","subtypes":["aeon","extraplanar"],"init":8,"senses":[{"type":"blindsense","modifier":"60 ft."},{"type":"darkvision","modifier":"90 ft."},{"type":"low-light vision"}],"ac":31,"ac_touch":18,"ac_flat_footed":26,"ac_mods":"+4 deflection, +4 Dex, +1 dodge, +13 natural, -1 size","hp":207,"hd":"18d10+108","hdvalue":18,"hp_mods":["fast healing 10"],"fort":18,"ref":12,"will":20,"immunities":["cold","critical hits","poison"],"resists":[{"type":"electricity","value":10},{"type":"fire","value":10}],"sr":27,"speed":[{"type":"fly","speed":40,"maneuverability":"good"}],"melee":"4 slams +23 (1d6+6 plus 1d6 cold and aging strike)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"confusion gaze"},{"type":"temporal strike"}],"spell_like_abilities_caster_level":18,"spell_like_abilities_concentration":27,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"augury"},{"spell":"greater teleport"},{"spell":"slow"}]},{"frequency":"1/day","spells":[{"spell":"dimensional lock"},{"spell":"moment of prescience"},{"spell":"temporal stasis"}]},{"frequency":"3/day","spells":[{"spell":"dimensional anchor"},{"spell":"haste"},{"spell":"plane shift"}]}],"strength":22,"dexterity":19,"constitution":21,"intelligence":24,"wisdom":28,"charisma":21,"baseatk":18,"cmb":25,"cmd":44,"cmd_special":"can't be tripped","feats":[{"feat":"Combat Casting"},{"feat":"Combat Reflexes"},{"feat":"Dodge"},{"feat":"Great Fortitude"},{"feat":"Hover"},{"feat":"Improved Initiative"},{"feat":"Lightning Reflexes"},{"feat":"Mobility"},{"feat":"Toughness"}],"skills":[{"skill":"Bluff","value":26},{"skill":"Fly","value":6},{"skill":"Heal","value":30},{"skill":"Intimidate","value":26},{"skill":"Knowledge (arcana, nature, religion)","value":33},{"skill":"Knowledge (history, planes)","value":36},{"skill":"Perception","value":30},{"skill":"Sense Motive","value":30},{"skill":"Spellcraft","value":28},{"skill":"Stealth","value":21},{"skill":"Use Magic Device","value":23}],"languages":["envisaging"],"sq":[{"type":"extension of all"},{"type":"void form"}],"environments":["any (Outer Planes)"],"organizations":["solitary","pair","tribunal (3 bythos)"],"treasure":"none","description_visual":"A shimmering, colorless mass congeals to form a four-armed humanoid shape with an eye-like pattern in its torso.","group":"Aeon","source":"PFRPG Bestiary 2","special_abilities":[{"type":"Aging Strike","kind":"Su","details":"If a bythos strikes a living target with two slam attacks in a single round, the bythos ages the creature, causing it to advance to the next age category if it fails a DC 24 Fortitude save. The victim gains all of the penalties from this aging and none of the bonuses. A venerable victim targeted by this ability dies if it fails a DC 24 Fortitude save. This process is reversible with greater restoration, limited wish, miracle, or wish. The save DC is Constitution-based."},{"type":"Confusion Gaze","kind":"Su","details":"Confusion for 1d4 rounds, 30 ft., Fortitude DC 24 negates. The save DC is Charisma-based."},{"type":"Temporal Strike","kind":"Su","details":"As a standard action, a bythos can touch a creature or object to displace it from time. If the target fails a DC 24 Fortitude save, it disappears from the present moment and reappears in the same location 1d4 rounds later as if no time had passed. If an object occupies that space, the creature appears in the closest available space to its original location-this displacement doesn't cause the creature any additional harm. The save DC is Charisma-based."}],"description":"The bythos are guardians of time and planar travel-indeed, to bythos, the act of aging isn'thing more than a highly specialized method of travel. Although bythos themselves have no additional method of traveling through time, they scour the multiverse, hunting for creatures that do have the ability to time-travel and may have abused this ability.\n\nFar more often, though, bythos seek out abuses of planar travel, such as tears in reality, regions where planes overlap, or creatures that abuse the use of planar travel. In some cases, such distortions are ignored, but in others, a bythos or even a full tribunal comes to assess and repair the damage. In most cases, \"repair\" is analogous to the death of the creature responsible for the distortions, but placing such creatures in temporal stasis can also solve the problem.\n\nWhile a bythos's body may seem to be made of smoke and vapor, it is strangely solid to the touch, feeling not dissimilar to dry stone. A bythos is 13 ft. tall and weighs 600 pounds.","ecology":"","habitat_society":""},{"name":"Clockwork Dragon","cr":16,"xp":76800,"alignment":"N","size":"Huge","type":"construct","subtypes":["clockwork"],"init":8,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"},{"type":"see invisibility"}],"ac":34,"ac_touch":14,"ac_flat_footed":28,"ac_mods":"+4 Dex, +2 dodge, +20 natural, -2 size","hp":177,"hd":"25d10+40","hdvalue":25,"fort":8,"ref":14,"will":8,"dr":"15/adamantine","immunities":["construct traits"],"resists":[{"type":"fire","value":20}],"sr":27,"weaknesses":["vulnerable to electricity"],"speed":[{"type":"land","speed":60},{"type":"fly","speed":100,"maneuverability":"average"},{"type":"swim","speed":60}],"melee":"bite +35 (4d6+12), 2 claws +35 (2d8+12), tail slap +30 (2d6+6), 2 wings +30 (2d6+6)","space":"15 ft.","reach":"15 ft. (15 ft. with bite)","special_attacks":[{"type":"adamantine weapons"},{"type":"breath weapon","details":"100-ft. line, 14d6 fire damage, Reflex DC 22 half, usable every 1d4 rounds"},{"type":"self-destruction"}],"strength":34,"dexterity":19,"wisdom":11,"charisma":1,"baseatk":25,"cmb":39,"cmd":55,"cmd_special":"+4 vs. trip","feats":[{"feat":"Improved Initiative","type":"bonus"},{"feat":"Lightning Reflexes","type":"bonus"}],"skills":[{"skill":"Fly","value":8},{"skill":"Perception","value":8},{"skill":"Swim","value":20}],"sq":[{"type":"difficult to create"},{"type":"efficient winding"},{"type":"swift reactions"}],"environments":["any land"],"organizations":["solitary"],"treasure":"none","description_visual":"Though made of thousands of metal parts, this masterpiece of gleaming metal glides through the air with impossible grace.","source":"PFRPG Bestiary 4","special_abilities":[{"type":"Adamantine Weapons","kind":"Ex","details":"The teeth and claws of a clockwork dragon are made of adamantine and have the qualities of a weapon made from that material."},{"type":"Efficient Winding","kind":"Ex","details":"Built for long and dangerous missions, a clockwork dragon can function for 3 days per Hit Die each time it's wound."},{"type":"Self-Destruction","kind":"Ex","details":"When a clockwork dragon's hit points are reduced to 10% of its total (17 in the case of most clockwork dragons) or less but are still above 0, the creature self-destructs on its next turn, bursting into an explosion of metal scraps and steam that deals 10d6 points of slashing damage plus 10d6 points of fire damage to all creatures within a 20-foot-radius burst. A successful DC 22 Reflex save halves the damage. The save is Charisma-based."}],"description":"While the clockwork goliaths possess more brute power, clockwork dragons' powerful breath weapons and mastery of flight make them more versatile and graceful killers. Designed for long flights and missions, the intricate winding mechanism of the clockwork dragon is more efficient than that of other clockwork constructs, partially because it reuses some of the energy generated by its intricate wings and the complex machinery of its breath weapon device. One of the most complicated and subtly crafted clockworks, its many moving parts are fortified by adamantine supports and fixtures, making this killing machine a brilliant mix of intricacy and unyielding terror. The basic chassis and internal workings of the clockwork dragons are highly adaptable, and many variants of the clockwork dragon exist. Clockwork dragons are typically 20 ft. long from snout to the tip of its tail, and weigh nearly 75 tons.\n\nVARIANT CLOCKWORK DRAGONS The following are a number of variant clockwork dragons. Some clockwork dragons exhibit more than one of these variations.\n\nAcid Breath (CR +0): Equipped with an internal fountain of caustic liquid, this type of clockwork dragon replaces its fire breath with a 60-foot line of acid. Targeted creatures take 10d8 points of acid damage (Reflex DC 22 half).\n\nDestroyer (CR + 0): These clockwork dragons are used as highly mobile and powerful siege engines. While the destroyer clockwork dragon lacks a breath weapon, as a full-round action taken while on solid ground, it can move its gears to pull its wings apart and to rise up as a heavy bombard. The body of the clockwork is used as the platform for the bombard, and the internal workings of the clockwork can load the bombard without a crew, though it still takes five full-round actions on the part of the clockwork to load the bombard. The clockwork dragon can also take the actions necessary to aim the bombard. A clockwork dragon carries enough ammunition to fire the bombard 10 times.\n\nFlaming Tar Breath (CR +1): Instead of breathing fire, some clockwork dragons spray a 30-foot cone of flaming tar. Creatures in the area of effect take 14d6 points of fire damage and are entangled in a thick layer of flaming tar. A successful DC 22 Reflex save halves the damage and negates the entangled effect. Creatures are entangled for 5 rounds as the tar burns. Entangled creatures take 3d6 points of fire damage each round on their turn. Spending a full-round action and succeeding at a DC 22 Reflex save removes the tar, freeing the trapped creature from the entanglement and further fire damage.\n\nInfiltrator (CR + 1): These clockwork dragons are more subtle and nimble than those of other clockwork dragons. An infiltrator clockwork dragon can rearrange its movable parts into very serpentine and compact shapes, which gives it the compression ability. Furthermore, its parts are coated with a black, noise-dampening resin, granting it a +8 racial bonus on Stealth checks (typically Stealth +0). Finally, it's infused with magic allowing it, as a standard action, to become invisible as the greater invisibility spell (CL 15th) three times per day. The infiltrator clockwork dragon's invisibility is a supernatural ability.\n\nMithral (CR +0): This variant loses its adamantine weapons and its DR, which are replaced by greater flight capability thanks to its spell-infused mithral parts. Its land and swim speeds increase to 70 ft., and its fly speed increases to 200 ft. with good maneuverability. In addition, once per day as a swift action, it can gain the benefits of the haste spell for 1d4 rounds.\n\nRust Breath (CR +0): Rust-breath clockwork dragons don't breathe fire. Instead, the creatures breathe out a fine mist of an alchemical solvent that instantly rusts exposed metals. This so-called \"rust breath\" issues forth in a 60-foot line. Creatures can attempt a DC 22 Reflex save to avoid the effect for attended items; however, they need to make a separate attempt for each exposed item. Each alchemical dragon can hold enough of the alchemical solvent to make up to three breath weapon attacks before the solvent must be refilled manually, which takes 10 minutes. These clockwork dragons are made of ironwood, adamantine, and other resistant materials immune to rusting of any form.\n\nSleep Gas Breath (CR +0): This clockwork dragon's breath weapon is replaced with tanks of sleep gas. When the clockwork breathes out this gas in a 30-foot cone, creatures within the cone must succeed a DC 22 Will save or fall asleep for 1d6+10 rounds. Clockwork dragons with this breath weapon tend to have either the infiltrator or mithral variants, and often they have both variants. These clockwork dragons excel at missions that require stealth and precision rather than brute force.\n\nConstruction\n\nThe clockwork dragon is a masterpiece of clockwork construction and is exceptionally difficult to create. The creator must begin with crafted clockwork pieces worth 25,000 gp.\n\nCLOCKWORK DRAGON\n\nCL 18th; Price 300,000 gp Construction Requirements Craft Construct, animate objects, geas/quest, and limited wish, creator must be at least CL 18th; Skill Craft (clockwork) DC 20; Cost 162,500 gp","ecology":"","habitat_society":""},{"name":"Ecorche","cr":16,"xp":76800,"alignment":"CE","size":"Large","type":"undead","init":9,"senses":[{"type":"darkvision","modifier":"60 ft."}],"auras":["frightful presence (60 ft., DC 26)"],"ac":30,"ac_touch":14,"ac_flat_footed":25,"ac_mods":"+5 Dex, +16 natural, -1 size","hp":209,"hd":"22d8+110","hdvalue":22,"hp_mods":["fast healing 5"],"fort":12,"ref":12,"will":15,"defensive_abilities":["channel resistance +2"],"dr":"15/good and silver","immunities":["acid","undead traits"],"speed":[{"type":"land","speed":30}],"melee":"2 claws +27 (3d6+11/19-20)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"bleed","details":"1 Con drain"},{"type":"rend","details":"2 claws, 3d6+11 plus bleed and seize skin"}],"strength":32,"dexterity":20,"intelligence":9,"wisdom":11,"charisma":21,"baseatk":16,"cmb":28,"cmd":43,"feats":[{"feat":"Awesome Blow"},{"feat":"Blinding Critical"},{"feat":"Combat Reflexes"},{"feat":"Critical Focus"},{"feat":"Improved Bull Rush"},{"feat":"Improved Critical (claw)"},{"feat":"Improved Initiative"},{"feat":"Iron Will"},{"feat":"Power Attack"},{"feat":"Stand Still"},{"feat":"Weapon Focus (claw)"}],"skills":[{"skill":"Disguise","value":30},{"skill":"Perception","value":25},{"skill":"Stealth","value":26}],"languages":["Common"],"sq":[{"type":"wear skin"}],"environments":["any land"],"organizations":["solitary","gang (2-4)"],"treasure":"none","description_visual":"This brawny creature has had its skin completely flensed from its form, revealing the violent pulsing of its massive, exposed muscles.","source":"PFRPG Bestiary 3","special_abilities":[{"type":"Seize Skin","kind":"Su","details":"Whenever an ecorche damages a target with its rend ability, the target must succeed at a DC 25 Fortitude save to resist being skinned alive. Those who fail the save become staggered and take 1 point of Constitution drain per round. Both of these effects are permanent but can be removed with a regenerate or heal spell (or 1 round of regeneration). The ecorche can use its wear skin ability to don a skin stolen in this way as a full-round action. The save DC is Dexterity-based."},{"type":"Wear Skin","kind":"Su","details":"An ecorche can steal the skin of a dead Small, Medium, or Large humanoid and wear it as its own. When it does this, the ecorche takes on the creature's size and appearance and gains a +10 bonus on Disguise checks made to impersonate the victim. While wearing a stolen skin, an ecorche cannot use its frightful presence. This stolen skin is preserved while the ecorche wears it, but is destroyed if the ecorche takes more than 10 points of damage or if the ecorche chooses to destroy the skin as a standard action. Those within 60 ft. who see an ecorche's stolen skin destroyed are immediately subjected to its frightful presence and take a -5 penalty on the related Will save. An ecorche reverts to its normal size if its stolen skin is destroyed."}],"description":"The bodyguards and spies of undead masterminds, ecorches appear as gory giants with musculatures overdeveloped by infusions of necromantic toxins and grafts of reanimated sinew. Although its natural form possesses no skin, an ecorche can steal the flesh of another creature, flaying its victim in mere seconds and leaving it in unimaginable shock and pain with only moments to seek aid before perishing. Yet this gruesome act of violence is only the first stage of the chaos an ecorche spreads with its violence.\n\nAn ecorche possesses incredible control over its gruesome form, allowing it to compress its body into the skin of a much smaller creature. Wearing such grisly garb, these terrors walk among the living, doing the bidding of their terrible masters or searching for more inf luential individuals to murder, skin, and impersonate. If an ecorche's unholy nature is revealed, the monster is quick to dispose of its nowuseless disguise, bursting from the suit of flesh and exposing its terrible form to the unprepared, few of whom can withstand such unabashed gore.\n\nAn ecorche stands approximately 8-1/2 ft. tall and weighs upward of 600 pounds.","ecology":"","habitat_society":""},{"name":"Elder Sphinx","cr":16,"xp":76800,"alignment":"N","size":"Gargantuan","type":"magical beast","init":5,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"},{"type":"true seeing"}],"ac":29,"ac_touch":7,"ac_flat_footed":28,"ac_mods":"+1 Dex, +22 natural, -4 size","hp":241,"hd":"21d10+126","hdvalue":21,"fort":18,"ref":15,"will":19,"defensive_abilities":["enciphered mind"],"dr":"15/adamantine and magic","immunities":["petrification"],"sr":27,"speed":[{"type":"land","speed":40},{"type":"fly","speed":60,"maneuverability":"poor"}],"melee":"2 claws +31 (2d6+14), 2 wings +26 (2d6+7)","space":"20 ft.","reach":"15 ft.","special_attacks":[{"type":"litany of riddles"},{"type":"pounce"},{"type":"rake","details":"2 claws +31, 2d6+14"},{"type":"trample","details":"2d6+21, DC 34"}],"spell_like_abilities_caster_level":20,"spell_like_abilities_concentration":26,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"comprehend languages"},{"spell":"detect magic"},{"spell":"nondetection"},{"spell":"read magic"},{"spell":"true seeing"}]},{"frequency":"1/day","spells":[{"spell":"commune"},{"spell":"contact other plane"},{"spell":"legend lore"}]},{"frequency":"3/day","spells":[{"spell":"clairaudience/clairvoyance"},{"spell":"greater dispel magic"},{"spell":"hallucinatory terrain"},{"spell":"locate object"},{"spell":"remove curse"},{"spell":"sirocco"}]},{"frequency":"1/week","spells":[{"spell":"symbol of fear","details":"any one of the following"},{"spell":"symbol of persuasion"},{"spell":"symbol of sleep"},{"spell":"symbol of vulnerability"},{"spell":"symbol of weakness","details":"all symbols last for 1 week maximum"}]}],"strength":39,"dexterity":12,"constitution":23,"intelligence":26,"wisdom":30,"charisma":25,"baseatk":21,"cmb":39,"cmb_special":"+2 vs. bull rush","cmd":50,"cmd_special":"+2 vs. bull rush, +4 vs. trip","feats":[{"feat":"Alertness"},{"feat":"Awesome Blow"},{"feat":"Flyby Attack"},{"feat":"Improved Bull Rush"},{"feat":"Improved Initiative"},{"feat":"Improved Iron Will"},{"feat":"Improved Vital Strike"},{"feat":"Iron Will"},{"feat":"Lightning Reflexes"},{"feat":"Power Attack"},{"feat":"Vital Strike"}],"skills":[{"skill":"Diplomacy","value":20},{"skill":"Fly","value":8},{"skill":"Intimidate","value":15},{"skill":"Knowledge (arcana)","value":20},{"skill":"Knowledge (dungeoneering)","value":20},{"skill":"Knowledge (engineering)","value":15},{"skill":"Knowledge (geography)","value":20},{"skill":"Knowledge (history)","value":20},{"skill":"Knowledge (local)","value":20},{"skill":"Knowledge (nature)","value":20},{"skill":"Knowledge (nobility)","value":20},{"skill":"Knowledge (planes)","value":20},{"skill":"Knowledge (religion)","value":20},{"skill":"Linguistics","value":15},{"skill":"Perception","value":27},{"skill":"Sense Motive","value":24},{"skill":"Spellcraft","value":28},{"skill":"Use Magic Device","value":20}],"languages":["Abyssal","Aquan","Ancient Osiriani","Auran","Celestial","Common","Draconic","Giant","Ignan","Infernal","Jistka","Sphinx","Sylvan","Tekritanin","Terran","telepathy 100 ft."],"sq":[{"type":"enigma"},{"type":"sphinx monolith"}],"environments":["warm deserts"],"organizations":["solitary"],"treasure":"standard","description_visual":"The brooding face of this towering limestone statue of a gynosphinx reflects a harsh wisdom acquired through untold ages of experience.","group":"Sphinx","source":"AP 83","special_abilities":[{"type":"Enciphered Mind","kind":"Su","details":"The forbidden knowledge elder sphinxes have accumulated is etched on their psyches, and it causes great harm to those who attempt to make psychic contact. Any creature attempting to contact an elder sphinx's mind or read its thoughts with a divination spell or similar ability must succeed at a DC 27 Will save or be overwhelmed by the chaos and vast scope of the knowledge within. Those who fail are affected by feeblemind. An elder sphinx can willingly suppress this ability at will as a free action. This is a mind-affecting effect, and the save DC is Charisma-based."},{"type":"Enigma","kind":"Su","details":"Elder sphinxes have removed themselves from the mundane world to contemplate the mysteries of the universe-and beyond. To facilitate this, they possess an uncanny ability to elude detection and discovery by those that could possibly interrupt their meditations. Any creature (other than another sphinx), that leaves line of sight of an elder sphinx for more than 1 hour must succeed at a DC 27 Will save or be unable to recall details of the encounter, as if the sphinx cast modify memory to eliminate all recollection of itself. The exact details of this memory loss are decided by the elder sphinx subconsciously during the encounter and it may eliminate up to an hour of memories. This is a mind-affecting compulsion effect and the save DC is Charisma-based."},{"type":"Litany of Riddles","kind":"Su","details":"As a standard action, an elder sphinx can telepathically project a befuddling series of riddles, puzzles, and logic paradoxes at all creatures in a 60-foot cone. Creatures caught in this effect must succeed at a DC 27 Will save or be stunned for 1d4 rounds. Creatures that succeed against this effect glean snippets of lore from this brush with the sphinx's mind, granting them a +5 insight bonus on all Knowledge checks for 1 hour and the ability to attempt Knowledge checks with a DC higher than 10 untrained. Once a creature successfully saves against this ability, it can't be affected by the same elder sphinx's litany of riddles for 24 hours. This is a mind-affecting effect and the save DC is Charisma-based."},{"type":"Sphinx Monolith","kind":"Su","details":"An elder sphinx can enter a state of suspended animation and transform its massive body into a stone monument. This transformation takes 1 minute to complete, during which the elder sphinx is immobile. Once it transforms into its monolith form, the elder sphinx's body hardens to stone, granting it hardness 30 and 350 hit points. If the elder sphinx's stony body is reduced to 0 hit points, it is destroyed and the elder sphinx is slain. While transformed, an elder sphinx doesn't need to breathe, eat, drink, or sleep. The elder sphinx is aware of its surroundings and it can use astral projection at will when in this form. Anytime an elder sphinx's body takes damage while using astral projection, its astral form immediately becomes aware that it is in danger and can, as a free action, end the astral projection and begin reverting back to its natural form (though the process still takes 1 minute). When an elder sphinx ends its transformation, it is immediately healed of all hit point damage it may have sustained while transformed. An elder sphinx can remain in its sphinx monolith form indefinitely."}],"description":"Older than most modern civilizations, elder sphinxes are the wisest and most venerable of sphinx kind. Though they have long since calcified into creatures of living limestone, these ancient creatures serve eternally as guardians, not of temples or other such terrestrial sites, but of forbidden knowledge and lore, much of which is beyond the understanding of lesser beings. Elder sphinxes are highly protective of the vast wealth of information they possess and strive to defend it from those they deem unworthy.\n\nEcology\n\nSphinxes gradually become more sedentary over their long lifespans as they lose their inclination toward physical activity. The eldest and most knowledgeable sphinxes undergo a transformation that allows them to remain undisturbed as they ponder the knowledge they've obtained. They turn into creatures of living limestone and grow to tremendous proportions, until they resemble ancient and weathered statues. No longer content with the Material Plane, elder sphinxes cast their consciousnesses out into the Astral Plane and beyond in search of the secrets of the universe, as their mortal hunger for nourishment is replaced by a metaphysical hunger for knowledge.\n\nHabitat & Society\n\nScholars claim that some elder sphinxes predate even the Age of Darkness and thus possess firsthand knowledge of the world as it once was, and have learned of the contemporary world only through their astral wandering or during the rare times they walk in their corporeal form. Whatever purpose they served in their youth has long since been forgotten or abandoned, leaving them to pursue more esoteric ambitions. These ancient creatures exist solely to seek out new information and to understand the great mysteries of the universe while their stony physical remains sit idle as time passes them by. In time, these elder sphinxes come to be seen as monuments, and sometimes humanoid cultures gather around them and worship them\n\nas idols. Infrequently, elder sphinxes can be coaxed to trade ancient knowledge for more current information or for arcane secrets they have yet to divine from the planes. Finding knowledge or information beyond an elder sphinx's experiences, however, is as monumental a task as locating one of their kind.\n\nElder sphinxes have little to no contact with other sphinxes. This only occurs when a younger, less powerful sphinx seeks out one of these magnificent specimens to plead for lost knowledge. When elder sphinxes do come into contact with one another, it is always a meeting of great purpose, typically on a matter of such importance that it requires them to share their ancient wisdom and unfathomable lore.","ecology":"Sphinxes gradually become more sedentary over their long lifespans as they lose their inclination toward physical activity. The eldest and most knowledgeable sphinxes undergo a transformation that allows them to remain undisturbed as they ponder the knowledge they've obtained. They turn into creatures of living limestone and grow to tremendous proportions, until they resemble ancient and weathered statues. No longer content with the Material Plane, elder sphinxes cast their consciousnesses out into the Astral Plane and beyond in search of the secrets of the universe, as their mortal hunger for nourishment is replaced by a metaphysical hunger for knowledge.","habitat_society":"Scholars claim that some elder sphinxes predate even the Age of Darkness and thus possess firsthand knowledge of the world as it once was, and have learned of the contemporary world only through their astral wandering or during the rare times they walk in their corporeal form. Whatever purpose they served in their youth has long since been forgotten or abandoned, leaving them to pursue more esoteric ambitions. These ancient creatures exist solely to seek out new information and to understand the great mysteries of the universe while their stony physical remains sit idle as time passes them by. In time, these elder sphinxes come to be seen as monuments, and sometimes humanoid cultures gather around them and worship them\n\nas idols. Infrequently, elder sphinxes can be coaxed to trade ancient knowledge for more current information or for arcane secrets they have yet to divine from the planes. Finding knowledge or information beyond an elder sphinx's experiences, however, is as monumental a task as locating one of their kind.\n\nElder sphinxes have little to no contact with other sphinxes. This only occurs when a younger, less powerful sphinx seeks out one of these magnificent specimens to plead for lost knowledge. When elder sphinxes do come into contact with one another, it is always a meeting of great purpose, typically on a matter of such importance that it requires them to share their ancient wisdom and unfathomable lore."},{"name":"Ephialtes Kyton","cr":16,"xp":76800,"alignment":"LE","size":"Huge","type":"outsider","subtypes":["evil","extraplanar","kyton","lawful"],"init":6,"senses":[{"type":"darkvision","modifier":"60 ft."}],"auras":["frightful presence (30 ft., DC 22)"],"ac":30,"ac_touch":10,"ac_flat_footed":28,"ac_mods":"+8 armor, +2 Dex, +12 natural, -2 size","hp":243,"hd":"18d10+144","hdvalue":18,"hp_mods":["regeneration 5 (good weapons and spells, silver weapons)"],"fort":14,"ref":13,"will":14,"defensive_abilities":["chain armor"],"dr":"10/silver or good","immunities":["cold","fear","poison"],"resists":[{"type":"acid","value":10},{"type":"fire","value":10}],"sr":27,"speed":[{"type":"land","speed":30}],"melee":"bite +24 (2d6+8), 2 chains +25 (2d8+8/19-20), 2 claws +24 (1d8+8), tail +19 (1d8+4)","space":"15 ft.","reach":"15 ft. (30 ft. with chains)","special_attacks":[{"type":"breath weapon","details":"50-ft. cone, 2d8+8 piercing damage plus grab, Reflex DC 27 for half, usable every 1d4 rounds dancing chains"},{"type":"entrapping chains"},{"type":"pull","details":"breath weapon, 10 ft."},{"type":"rend","details":"2 chains, 2d8+12"}],"spell_like_abilities_caster_level":16,"spell_like_abilities_concentration":24,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"blur","details":"self only"},{"spell":"dimensional anchor"}]},{"frequency":"1/day","spells":[{"spell":"discern location"}]},{"frequency":"3/day","spells":[{"spell":"deeper darkness"},{"spell":"shadow walk"},{"spell":"silence"}]}],"strength":26,"dexterity":14,"constitution":26,"intelligence":10,"wisdom":12,"charisma":16,"baseatk":18,"cmb":28,"cmb_special":"+4 vs. grapple or pull","cmd":40,"cmd_special":"+4 vs. trip","feats":[{"feat":"Alertness"},{"feat":"Bleeding Critical"},{"feat":"Combat Reflexes"},{"feat":"Critical Focus"},{"feat":"Improved Critical (chains)"},{"feat":"Improved Initiative"},{"feat":"Iron Will"},{"feat":"Stand Still"},{"feat":"Weapon Focus (chains)"}],"skills":[{"skill":"Bluff","value":12},{"skill":"Climb","value":15},{"skill":"Escape Artist","value":13},{"skill":"Intimidate","value":24},{"skill":"Knowledge (planes)","value":13},{"skill":"Perception","value":24},{"skill":"Sense Motive","value":18},{"skill":"Stealth","value":15},{"skill":"Survival","value":22}],"languages":["Infernal"],"environments":["any (Shadow Plane)"],"organizations":["solitary","team (2-8)"],"treasure":"Value standard","description_visual":"Amid a roiling cloud of deepest dark, the rattle of chains and heavy footfalls announce a being of immense size. An infernal, gasping hiss draws the darkness back, revealing a tortured, fourlegged fiend of exposed bone and ragged flesh draped in chains. Barbs and hooks hang from these wrought iron bands, matching the fiend's tail as they writhe like snakes in search of prey.","group":"KYTON","source":"AP 30","special_abilities":[{"type":"Breath Weapon","kind":"Su","details":"As a full-round action, an ephialtes kyton may exhale a spread of barbed, grappling chains anchored within its massive maw, targeting up to six creatures in a 50-foot cone. Those failing a DC 27 Reflex save suffer 2d8+8 points of piercing damage and the kyton may make a combat maneuver check as an immediate action to grapple each victim with the animate chains. A successful save cuts the damage in half and avoids the grapple opportunity. Those successfully grappled by the chains become subject to the kyton's pull ability. A kyton cannot use its breath weapon again while it is grappling or pulling creatures with its breath weapon chains. Otherwise, it may use the breath weapon once every 1d4 rounds. The save DC is Constitution-based. An ephialtes kyton's chains (hardness 10, hp 10, Break DC 26) can be broken, or attacked by making a sunder attempt. If the chain is currently grappling a target, the attacker gains a +4 circumstance bonus on the CMB check to sunder. Severing a chain deals no damage to a kyton."},{"type":"Chain Armor","kind":"Ex","details":"The chains that adorn an ephialtes kyton grant it a +8 armor bonus, but are not treated as armor for the purpose of arcane spell failure, armor check penalties, maximum Dexterity, weight, or proficiency."},{"type":"Dancing Chains","kind":"Su","details":"An ephialtes kyton can control up to four chains within 30 ft. as a standard action, making the chains dance or move as it wishes. In addition, the kyton can increase these chains' length by up to 15 ft. and cause them to sprout razor-sharp barbs. The chains attack as effectively as the kyton itself. If a chain is in another creature's possession, the creature can attempt a DC 22 Will save to break the ephialtes kyton's power over that chain. If the save is successful, the kyton cannot attempt to control that particular chain again for 24 hours or until the chain leaves the other creature's possession. An ephialtes kyton can climb chains it controls at its normal speed without making Climb checks. The save DC is Charisma-based."},{"type":"Entrapping Chains","kind":"Su","details":"With a successful combat maneuver check, an ephialtes kyton may transfer an adjacent creature grappled by the kyton's breath weapon chains to the chains adorning its body, giving the target the pinned condition while the kyton deals with remaining foes. The kyton doesn't retain the grappled condition while pinning such creatures. Pinned victims can free themselves with a combat maneuver check to break the pin or an Escape Artist check. Other creatures can attempt to free pinned victims by making a sunder attempt (hardness 10, hp 10). An ephialtes kyton may entrap 1 Large, 2 Medium, 8 Small, 32 Tiny, or 128 Diminutive or smaller opponents."},{"type":"Pull","kind":"Ex","details":"An ephialtes kyton has a +4 racial bonus on CMB checks made using its pull special attack."}],"description":"Sadistic hunters and tormentors of all living souls, ephialtes kytons usually roam the planes in service to the lords of Hell and Shadow, but occasionally in pursuit of their own fell interests. They ruthlessly abduct the innocent and retrieve the damned, dragging their victims into the fires of Hell or the gnashing, wailing dark of the Plane of Shadow. They have no fear, tracking their chosen prey regardless of distance or challenge, and shackle dragons, giants, and humanoids alike for their eternal torturous rewards. Ephialtes kytons travel in silent grace while cloaked in darkness, but drop their stealthy veils when ready to intimidate those they've come to collect or punish. Then, their frightening gaze matches the deadly intent of the chains piercing their flesh. These animated, wrought iron bands serve as protection and weapons in the hands or claws of all kytons, but may also bind and lash their victims to the ephialtes' ever-bleeding hide to carry them into the Great Beyond. A typical ephialtes stands 25 ft. tall and weighs over 15 tons with the combined burden of their deadly chains. Ecology An ephialtes kyton results from the ritual transformation of a lesser kyton which has slain or bound 999 mortal victims in the soulless dark of the Shadow Plane. Thereafter, it gains the ability to shadow walk and expand its access to other planes without waiting for summoners to request its services. Eternally vigilant and opportunistic, ephialtes kytons hunt for further victims for young kytons to practice upon. Because of their honed expertise in capturing and tormenting souls, ephialtes are highly useful to the diabolical elite-both mortals and the immortal lords of Hell-who seek out ephialtes kytons as fell servants. Some kytons willingly align themselves with the rulers of Hell, taking further delight in the various torments available in that realm. Habitat & Society Ephialtes kytons shepherd and rule over the entirety of kyton society. Though not especially cunning compared to other fiends, they still possess a fierce loyalty to their own kind and adhere to a rigid hierarchy of power and achievement. Their homes within the Plane of Shadow remain eternally hidden, with the sounds of flesh-flensing chains providing the only insight into their torturous methods. Few outsiders understand the purpose of these elaborate torments, though rumors suggest they further empower the ephialtes to ever-greater transformations. Summoning Ephialtes Kytons As long as a conjurer doesn't interrupt an ongoing hunt, most ephialtes kytons relish being summoned, looking forward to the sport of chasing down newly assigned prey or punishing those who fail to properly bind them. Any Charisma check made as part of the greater planar binding spell to convince an ephialtes kyton to undertake a mission other than the murder, abduction, or torture of specific victims suffers a -2 penalty. Once an ephialtes kyton accepts an assignment, it demands 1,000 gp paid in black onyx or opals for every Hit Die its target possesses. If the summoner cannot pay the price in the required gems, the kyton only partially carries out the requested service-maiming instead of murdering, abducting for only a limited time (typically 1d4+3 days), or only torturing a victim until it answers a single question as part of an interrogation. If a summoner tries to force an ephialtes kyton to perform a different type of service or accept a different form of payment, the kyton takes offense and all of the summoner's future Charisma related interactions with the ephialtes suffer a -2 penalty. Once an ephialtes kyton has agreed to a task, only its assigned prey interests it. Ephialtes kytons always offer to dispose of such victims by taking them to the Shadow Plane so they can help lesser kytons obtain the necessary number of souls to become ephialtes.","ecology":"An ephialtes kyton results from the ritual transformation of a lesser kyton which has slain or bound 999 mortal victims in the soulless dark of the Shadow Plane. Thereafter, it gains the ability to shadow walk and expand its access to other planes without waiting for summoners to request its services. Eternally vigilant and opportunistic, ephialtes kytons hunt for further victims for young kytons to practice upon. Because of their honed expertise in capturing and tormenting souls, ephialtes are highly useful to the diabolical elite-both mortals and the immortal lords of Hell-who seek out ephialtes kytons as fell servants. Some kytons willingly align themselves with the rulers of Hell, taking further delight in the various torments available in that realm.","habitat_society":"Ephialtes kytons shepherd and rule over the entirety of kyton society. Though not especially cunning compared to other fiends, they still possess a fierce loyalty to their own kind and adhere to a rigid hierarchy of power and achievement. Their homes within the Plane of Shadow remain eternally hidden, with the sounds of flesh-flensing chains providing the only insight into their torturous methods. Few outsiders understand the purpose of these elaborate torments, though rumors suggest they further empower the ephialtes to ever-greater transformations. Summoning Ephialtes Kytons As long as a conjurer doesn't interrupt an ongoing hunt, most ephialtes kytons relish being summoned, looking forward to the sport of chasing down newly assigned prey or punishing those who fail to properly bind them. Any Charisma check made as part of the greater planar binding spell to convince an ephialtes kyton to undertake a mission other than the murder, abduction, or torture of specific victims suffers a -2 penalty. Once an ephialtes kyton accepts an assignment, it demands 1,000 gp paid in black onyx or opals for every Hit Die its target possesses. If the summoner cannot pay the price in the required gems, the kyton only partially carries out the requested service-maiming instead of murdering, abducting for only a limited time (typically 1d4+3 days), or only torturing a victim until it answers a single question as part of an interrogation. If a summoner tries to force an ephialtes kyton to perform a different type of service or accept a different form of payment, the kyton takes offense and all of the summoner's future Charisma related interactions with the ephialtes suffer a -2 penalty. Once an ephialtes kyton has agreed to a task, only its assigned prey interests it. Ephialtes kytons always offer to dispose of such victims by taking them to the Shadow Plane so they can help lesser kytons obtain the necessary number of souls to become ephialtes."},{"name":"Fjord Linnorm","cr":16,"xp":76800,"alignment":"CE","size":"Gargantuan","type":"dragon","subtypes":["aquatic"],"init":10,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"},{"type":"scent"},{"type":"true seeing"}],"ac":30,"ac_touch":12,"ac_flat_footed":24,"ac_mods":"+6 Dex, +18 natural, -4 size","hp":248,"hd":"16d12+144","hdvalue":16,"hp_mods":["regeneration 10 (cold iron)"],"fort":19,"ref":18,"will":15,"defensive_abilities":["freedom of movement"],"dr":"15/cold iron","immunities":["cold","curse effects","mind-affecting effects","paralysis","poison","sleep"],"sr":27,"speed":[{"type":"land","speed":30},{"type":"fly","speed":100,"maneuverability":"average"},{"type":"swim","speed":60}],"melee":"bite +25 (2d8+13/19-20 plus poison), 2 claws +25 (2d6+13), tail +20 (2d6+6 plus grab)","space":"20 ft.","reach":"20 ft.","special_attacks":[{"type":"breath weapon"},{"type":"constrict","details":"tail, 2d6+19"},{"type":"death curse"}],"strength":36,"dexterity":23,"constitution":28,"intelligence":5,"wisdom":21,"charisma":26,"baseatk":16,"cmb":33,"cmb_special":"+4 vs. grapple","cmd":49,"cmd_special":"can't be tripped","feats":[{"feat":"Blind-Fight"},{"feat":"Combat Reflexes"},{"feat":"Improved Bull Rush"},{"feat":"Improved Critical (bite)"},{"feat":"Improved Initiative"},{"feat":"Lightning Reflexes"},{"feat":"Power Attack"},{"feat":"Vital Strike"}],"skills":[{"skill":"Fly","value":19},{"skill":"Perception","value":24},{"skill":"Swim","value":40}],"languages":["Aklo","Draconic","Sylvan"],"sq":[{"type":"amphibious"}],"environments":["cold mountains coastlines"],"organizations":["solitary"],"treasure":"triple","description_visual":"This massive, eel-like dragon has two webbed talons. Its tail ends in large and powerful-looking flukes.","group":"Linnorm","source":"PFRPG Bestiary 3","special_abilities":[{"type":"Breath Weapon","kind":"Su","details":"Once every 1d4 rounds as a standard action, a fjord linnorm can expel a 120-foot line of icy fluid, dealing 16d8 points of cold damage to all creatures struck (Reflex DC 27 for half damage). The freezing liquid quickly hardens to sheets of ice, causing any creature that takes damage to move at only half its normal speed for 1d4 rounds. A DC 27 Strength check made as a full-round action allows a character to break free of the ice before this duration expires. The save DC and Strength check DC are Constitution-based."},{"type":"Death Curse","kind":"Su","details":"Curse of Drowning: save Will DC 26; effect creature can never gain the benefit of water breathing, and if it possesses this ability, loses it as long as it suffers the curse. In addition, the creature can hold its breath only half as long as normal, and whenever the cursed creature holds its breath, it functions as if sickened."},{"type":"Poison","kind":"Ex","details":"Bite-injury; save Fort DC 27; frequency 1/round for 10 rounds; effect 3d6 cold damage and 1d6 Con drain; cure 2 consecutive saves."}],"description":"Fjord linnorms dwell among the deep waters that grace northern coastlines where fingers of land create complex rivulets, venturing out to sea to feed on sharks and whales when they cannot find settlements or traveling caravans to savage. As their favored haunts often overlap with coastal trade routes, regions known to be within the territory of a fjord linnorm are often avoided by ships. Fjord linnorms are not particularly adept at capsizing ships, as are some other large aquatic monsters, but one might argue that such tactics are unnecessary for a creature the size and power of a fjord linnorm in the first place.\n\nBoth the curse and poison of a fjord linnorm are extremely dangerous for those who frequent the waterways of the north. The fjord linnorm's curse is particularly devastating to aquatic creatures, and such beings are careful to avoid any possible conflict with such linnorms.\n\nA fjord linnorm is 60 ft. long and weighs just over 10,000 pounds.","ecology":"","habitat_society":""},{"name":"Flesh Colossus","cr":16,"xp":76800,"alignment":"N","size":"Gargantuan","type":"construct","subtypes":["colossus","mythic"],"init":0,"senses":[{"type":"all-around vision"},{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"auras":["selective antimagic (20 ft.)","unnatural (30 ft.)"],"ac":30,"ac_touch":6,"ac_flat_footed":30,"ac_mods":"+24 natural, -4 size","hp":224,"hd":"16d10+136","hdvalue":16,"fort":5,"ref":5,"will":5,"dr":"10/epic","immunities":["electricity","construct traits"],"speed":[{"type":"land","speed":60}],"melee":"2 slams +28 (2d12+16/19-20/x3 plus grab) or stomp +28 (4d12+24 plus pinning stomp)","space":"20 ft.","reach":"20 ft.","special_attacks":[{"type":"constrict","details":"2d12+16"},{"type":"mythic power","details":"6/day, surge +1d8"},{"type":"mythic quickening"},{"type":"pinning stomp"}],"spell_like_abilities_caster_level":13,"spell_like_abilities_concentration":13,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"circle of death"}]},{"frequency":"3/day","spells":[{"spell":"waves of fatigue"}]}],"strength":42,"dexterity":11,"intelligence":3,"wisdom":10,"charisma":7,"baseatk":16,"cmb":36,"cmd":46,"feats":[{"feat":"Cleave","type":"mythic"},{"feat":"Great Cleave"},{"feat":"Greater Vital Strike"},{"feat":"Improved CriticalM (slam)"},{"feat":"Improved Vital Strike"},{"feat":"Power Attack","type":"mythic"},{"feat":"Toughness"},{"feat":"Vital Strike"}],"skills":[{"skill":"Intimidate","value":9},{"skill":"Perception","value":8}],"languages":["Common"],"sq":[{"type":"alternate form"},{"type":"mythic creation"},{"type":"mythic resilience"}],"environments":["any land"],"organizations":["solitary"],"treasure":"none","description_visual":"This enormous monstrosity looks like a pile of fresh humanoid bodies shoved into a shambling humanoid shape.","group":"Flesh","source":"PFRPG Bestiary 4","special_abilities":[{"type":"Alternate Form","kind":"Ex","details":"As a full-round action, a flesh colossus can break apart into four composite creatures. These composite creatures are identical to flesh golems but lack the golem's DR and the berserk and immunity to magic abilities. They gain DR 5/epic, electricity absorption, and selective antimagic aura (10 ft.). Divide the colossus's current total hit points by 4 to determine how many hit points each composite creature has. Reverting into a single form requires all of the remaining composite creatures to be adjacent to each other and a full-round action. When this occurs, add up the remaining hit points to determine the colossus's total hit points."},{"type":"Selective Antimagic Aura","kind":"Su","details":"Spells and abilities with the electricity descriptor or that deal electricity damage are unaffected by this field, as are necromancy spells and effects."}],"description":"A flesh colossus consists of hundreds of corpses assembled into a macabre whole. Its stands roughly 60 ft. tall and weighs about 150,000 pounds.\n\nConstruction\n\nCreating a flesh colossus requires at least 500 humanoid corpses with a total cost of 10,000 gp.\n\nFLESH COLOSSUS CL 12th; Price 120,000 gp\n\nConstruction\n\nRequirements Craft Construct, Mythic Crafter 6th mythic tier, animate dead, antimagic field, gentle repose, limited wish; Skill Heal DC 25; Cost 70,000 gp","ecology":"","habitat_society":""},{"name":"Gallowdead","cr":16,"xp":76800,"alignment":"CE","size":"Medium","type":"undead","init":8,"senses":[{"type":"darkvision","modifier":"60 ft."}],"auras":["whispers (30 ft., DC 27)"],"ac":31,"ac_touch":15,"ac_flat_footed":26,"ac_mods":"+4 Dex, +1 dodge, +16 natural","hp":228,"hd":"24d8+120","hdvalue":24,"fort":13,"ref":12,"will":17,"defensive_abilities":["channel resistance +6"],"dr":"10/bludgeoning","immunities":["cold","undead traits"],"speed":[{"type":"land","speed":30}],"melee":"spiked chain +26 (2d4+10/19-20 plus chains of the dead) or 2 claws +25 (2d8+7)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"chains of the dead Space","details":"5 ft."},{"type":"Reach 5 ft.","details":"10 ft. with spiked chain"}],"strength":24,"dexterity":19,"intelligence":11,"wisdom":16,"charisma":21,"baseatk":18,"cmb":25,"cmd":40,"feats":[{"feat":"Bleeding Critical"},{"feat":"Combat Reflexes"},{"feat":"Critical Focus"},{"feat":"Dodge"},{"feat":"Improved Critical (spiked chain)"},{"feat":"Improved Initiative"},{"feat":"Improved Vital Strike"},{"feat":"Lunge"},{"feat":"Power Attack"},{"feat":"Step Up"},{"feat":"Vital Strike"},{"feat":"Weapon Focus (spiked chain)"}],"skills":[{"skill":"Climb","value":34},{"skill":"Escape Artist","value":28},{"skill":"Intimidate","value":32},{"skill":"Swim","value":31}],"languages":["Common"],"environments":["any"],"organizations":["solitary","pair","plague (3-18)"],"treasure":"standard","description_visual":"This skeletal horror staggers under the weight of the massive hook and chain impaling the bones of its midsection.","source":"PFRPG Bestiary 4","special_abilities":[{"type":"Aura of Whispers","kind":"Su","details":"A gallowdead constantly whispers vile secrets and blasphemous chants. Any creature within 30 ft. of a gallowdead must succeed at a DC 27 Will save or be shaken for 1d4 rounds. Already shaken creatures that fail this saving throw become nauseated by the secrets revealed. Each round, an affected creature can make a new Will save to recover from the effect-once a creature recovers from a gallowdead's whispers, it is immune to this ability for 24 hours. Each overlapping whisper aura from additional gallowdead increases the save DC by 2. This is a language-based sonic effect. The save DC is Charisma-based."},{"type":"Chains of the Dead","kind":"Su","details":"When a gallowdead uses its spiked chain, the first attack that hits a foe during the gallowdead's turn deals an extra 12d6 points of negative energy damage (Will DC 27 half). This has no effect on undead creatures. In addition, the gallowdead can make a free combat maneuver check against its target with a +4 racial bonus. If the check succeeds, the target becomes grappled, but the gallowdead doesn't gain the grappled condition. The gallowdead can make a free combat maneuver check each round to maintain its grip on the victim, but can't take any special grapple actions against the victim except the move special action. When grappling a victim in this way, the gallowdead can't attack with its spiked chain. The save DC is Charisma-based."}],"description":"Some tyrants execute criminals, traitors, or those who dare insurrection on the end of hooked and spiked chains. Leaving the criminal to painfully hang and rot sends a message to those who would dare commit the same crimes. Sometimes such savage deaths have a strange and terrible consequence: the victim rises, grabs the instrument of its execution, and becomes a servant of those who condemned it.","ecology":"","habitat_society":""},{"name":"Grootslang","cr":16,"xp":76800,"alignment":"CE","size":"Gargantuan","type":"magical beast","init":4,"senses":[{"type":"darkvision","modifier":"120 ft."},{"type":"scent"}],"ac":31,"ac_touch":11,"ac_flat_footed":26,"ac_mods":"+4 Dex, +1 dodge, +20 natural, -4 size","hp":283,"hd":"21d10+168","hdvalue":21,"fort":20,"ref":16,"will":12,"dr":"10/magic","sr":27,"speed":[{"type":"land","speed":40},{"type":"swim","speed":30}],"melee":"bite +30 (4d8+13/19-20), 2 stomps +27 (2d6+6), tail slap +27 (2d6+6)","space":"20 ft.","reach":"20 ft.","special_attacks":[{"type":"impaling bite"},{"type":"thunderous stomp","details":"DC 28"},{"type":"trample","details":"2d6+19, DC 33"}],"strength":36,"dexterity":19,"constitution":26,"intelligence":15,"wisdom":20,"charisma":15,"baseatk":21,"cmb":38,"cmb_special":"+2 vs. bull rush","cmd":53,"cmd_special":"+2 vs. bull rush or trip","feats":[{"feat":"Awesome Blow"},{"feat":"Bleeding Critical"},{"feat":"Cleave"},{"feat":"Critical Focus"},{"feat":"Dodge"},{"feat":"Improved Bull Rush"},{"feat":"Improved Critical (bite)"},{"feat":"Mobility"},{"feat":"Multiattack"},{"feat":"Power Attack"},{"feat":"Spring Attack"}],"skills":[{"skill":"Acrobatics","value":15,"special":"+19 when jumping"},{"skill":"Bluff","value":4},{"skill":"Intimidate","value":12},{"skill":"Perception","value":28},{"skill":"Sense Motive","value":13},{"skill":"Stealth","value":10},{"skill":"Swim","value":45}],"languages":["Aquan","Common","Draconic"],"sq":[{"type":"aquatic elusion"},{"type":"hold breath"}],"environments":["warm lakes","warm rivers"],"organizations":["solitary"],"treasure":"double (at least 50% gems)","description_visual":"This enormous beast has the combined features of an elephant and a serpent. Its tremendous maw sports six frightening tusks.","source":"PFRPG Bestiary 3","special_abilities":[{"type":"Aquatic Elusion","kind":"Su","details":"As a standard action, a grootslang that is fully immersed in water can teleport to another body of water without error. This ability functions like tree stride, but the grootslang can exit from any body of water within 1 mile so long as both the entry and exit are wide enough for the creature to enter."},{"type":"Impaling Bite","kind":"Ex","details":"A grootslang can make a bite attack against any creature it is grappling. If this attack hits, it is automatically treated as a critical threat."},{"type":"Thunderous Stomp","kind":"Ex","details":"As a full-round action, a grootslang can rear up on its serpentine body to bring its massive forelimbs down with awesome force. The grootslang chooses two adjacent targets to be affected as though trampling them. In addition, each creature within 10 ft. must make a DC 28 Reflex save or be knocked prone. The save DC is Constitution-based."}],"description":"Legends claim that the grootslang is a primordial creature as old as the world itself. Such tales state that in those ancient days, the gods—new to the crafting of things—made a terrible mistake in the grootslang's creation, for they gave it tremendous strength, cunning, and intellect. Upon realizing their mistake, the gods split the grootslang into separate creatures and thus created the first elephants and the first snakes. But one of the original grootslangs escaped, and from this first sire all other grootslangs were born. Scholars debate the veracity of such stories, and have looked to either biological or magical explanations of the creature's origins, but nevertheless bards and sages alike agree that the grootslang's fearsome reputation is well deserved.\n\nA grootslang's thick, leathery hide has a metallic sheen and a dull copper color, shot through with thin veins of green. Both males and females grow to a length of 60 ft. and stand 20 ft. tall. Little differentiation exists between sexes save for a lighter green hue to the female's hide. Grootslangs can weigh 20 tons and live up to 500 years.\n\nAll grootslangs covet gems, particularly diamonds, and despite the creatures' lust for cruelty, victims can often bargain for their freedom by offering a grootslang enough precious gems.","ecology":"","habitat_society":""},{"name":"Hollow Serpent","cr":16,"xp":76800,"alignment":"NE","size":"Large","type":"undead","init":9,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"lifesense"}],"auras":["desiccation aura (30 ft., DC 26)"],"ac":31,"ac_touch":19,"ac_flat_footed":21,"ac_mods":"+9 Dex, +1 dodge, +12 natural, -1 size","hp":230,"hd":"20d8+140","hdvalue":20,"hp_mods":["fast healing 10"],"fort":14,"ref":17,"will":18,"defensive_abilities":["channel resistance +4","freedom of movement"],"dr":"10/magic and silver","immunities":["undead traits"],"sr":27,"speed":[{"type":"land","speed":50},{"type":"climb","speed":50}],"melee":"2 bites +23 (4d10+10 plus grab)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"channel negative energy","details":"8d6, DC 24, 9/day"},{"type":"constrict","details":"4d10+10 plus energy drain"},{"type":"energy drain","details":"1 level, DC 26"},{"type":"life-draining coils"}],"spell_like_abilities_caster_level":16,"spell_like_abilities_concentration":16,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"freedom of movement"}]},{"frequency":"1/day","spells":[{"spell":"horrid wilting"},{"spell":"waves of exhaustion"}]}],"strength":25,"dexterity":29,"intelligence":6,"wisdom":19,"charisma":22,"baseatk":15,"cmb":25,"cmb_special":"+4 vs. grapple","cmd":43,"cmd_special":"can't be tripped","feats":[{"feat":"Agile Maneuvers"},{"feat":"Channel Smite"},{"feat":"Dodge"},{"feat":"Great Fortitude"},{"feat":"Iron Will"},{"feat":"Lightning Reflexes"},{"feat":"Lunge"},{"feat":"Toughness"},{"feat":"Vital Strike"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Climb","value":28},{"skill":"Escape Artist","value":19},{"skill":"Perception","value":17},{"skill":"Stealth","value":18}],"languages":["Aklo","telepathy 100 ft."],"sq":[{"type":"swift strike"}],"environments":["any underground"],"organizations":["solitary","pair","nest (3-8)"],"treasure":"double","description_visual":"This creature looks like an oversized, empty snakeskin, its body covered in barbs and maw filled with jagged teeth.","source":"PFRPG Bestiary 3","special_abilities":[{"type":"Channel Negative Energy","kind":"Su","details":"As a standard action, a hollow serpent can channel negative energy in a 30-foot burst as a 16th-level evil cleric. This ability requires no divine focus. The save DC is Charisma-based."},{"type":"Desiccation Aura","kind":"Su","details":"A cloud of moisture-draining dust fills the air in a 30-foot radius around a hollow serpent. Living creatures within this area must make a DC 26 Fortitude save or take 1d6 points of Strength damage as water is leached from their flesh. Whether or not the save is successful, a creature cannot be affected again by the same hollow serpent's desiccation aura for 24 hours. Creatures without fleshy bodies are immune to this aura, while creatures with the aquatic or water subtypes take a -4 penalty on the saving throw. The save DC is Charisma-based."},{"type":"Life-Draining Coils","kind":"Su","details":"A hollow serpent seethes with negative energy capable of sapping the life force of creatures trapped within its coils. Every time a creature takes constriction damage from a hollow serpent, it gains one negative level. The hollow serpent also gains 5 temporary hit points for each negative level it bestows."},{"type":"Lifesense","kind":"Su","details":"A hollow serpent notices and locates living creatures within 60 ft., just as if it possessed the blindsight ability."},{"type":"Swift Strike","kind":"Ex","details":"When a hollow serpent takes a full-attack action, it can make two bite attacks instead of just one."}],"description":"Crafted from the shed skins of great snakes by serpentfolk necromancers and other foul spellcasters, hollow serpents are plagued by an eternal hunger they can never sate. The act of draining energy from living creatures blunts these supernatural pangs, driving the hollow serpent to constantly seek new prey.\n\nA hollow serpent is a difficult undead to create-most of them were crafted by a long-forgotten god of the serpentfolk and not by mortal spellcasters at all. The exact methods by which a mortal might create a hollow serpent are obscure, but most scholars have come to the conclusion that the use of powerful artifacts or the aid of a demigod may be required for such a feat.\n\nA hollow serpent is 15 ft. long and weighs 500 pounds.","ecology":"","habitat_society":""},{"name":"Horned Devil","cr":16,"xp":76800,"alignment":"LE","size":"Large","type":"outsider","subtypes":["devil","evil","extraplanar","lawful"],"init":8,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"see in darkness"}],"auras":["fear aura (5 ft., DC 23)"],"ac":35,"ac_touch":17,"ac_flat_footed":27,"ac_mods":"+8 Dex, +18 natural, -1 size","hp":217,"hd":"15d10+135","hdvalue":15,"hp_mods":["regeneration 5 (good weapons, good spells)"],"fort":18,"ref":17,"will":13,"dr":"10/good and silver","immunities":["fire","poison"],"resists":[{"type":"acid","value":10},{"type":"cold","value":10}],"sr":27,"speed":[{"type":"land","speed":30},{"type":"fly","speed":50,"maneuverability":"average"}],"melee":"+1 unholy spiked chain +26 (2d6+11 plus stun), bite +22 (2d8+5), tail +22 (2d6+5 plus infernal wound) or 2 claws +24 (2d6+10), bite +24 (2d8+10), tail +22 (2d6+5 plus infernal wound)","space":"10 ft.","reach":"10 ft.","spell_like_abilities_caster_level":16,"spell_like_abilities_concentration":25,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"dispel chaos"},{"spell":"dispel good"},{"spell":"greater teleport","details":"self plus 50 lbs. of objects only"},{"spell":"magic circle against good"},{"spell":"persistent image"}]},{"frequency":"1/day","spells":[{"spell":"summon","details":"level 6, 3 barbed devils, 35%"}]},{"frequency":"3/day","spells":[{"spell":"fireball"},{"spell":"lightning bolt"}]}],"strength":31,"dexterity":27,"constitution":28,"intelligence":14,"wisdom":22,"charisma":23,"baseatk":15,"cmb":26,"cmd":44,"feats":[{"feat":"Improved Bull Rush"},{"feat":"Improved Sunder"},{"feat":"Improved Vital Strike"},{"feat":"Iron Will"},{"feat":"Multiattack"},{"feat":"Power Attack"},{"feat":"Vital Strike"},{"feat":"Weapon Focus (spiked chain)"}],"skills":[{"skill":"Bluff","value":24},{"skill":"Diplomacy","value":21},{"skill":"Fly","value":15},{"skill":"Intimidate","value":24},{"skill":"Knowledge (planes)","value":20},{"skill":"Perception","value":24},{"skill":"Sense Motive","value":21},{"skill":"Spellcraft","value":20},{"skill":"Stealth","value":22}],"languages":["Celestial","Common","Draconic","Infernal","telepathy 100 ft."],"environments":["any (Hell)"],"organizations":["solitary","pair","wing (3-10)"],"treasure":"standard (+1 unholy spiked chain)","description_visual":"Bristling with terrible spines and a crown of deadly horns, this leering winged terror wields a whirling barbed chain.","group":"Devil","source":"PFRPG Bestiary","special_abilities":[{"type":"Infernal Wound","kind":"Su","details":"The damage a horned devil deals with its tail causes persistent wounds that deal 2d6 points of bleed damage. Bleeding caused in this way is difficult to staunch-a DC 26 Heal check stops the damage, and any attempt to heal a creature suffering from an infernal wound must succeed on a DC 26 caster level check or the spell doesn't function. Success indicates the healing works normally and stops all bleed effects."},{"type":"Stun","kind":"Su","details":"Whenever a horned devil hits with a spiked chain attack, the opponent must succeed on a DC 27 Fortitude save or be stunned for 1d4 rounds. This ability is a function of the horned devil, not of the spiked chain. The save DC is Strength-based."}],"description":"Among the deadliest of the archdevils' warriors and able commanders of lesser fiends, horned devils spread the rule of Hell wherever they tread. These greater devils are trained, forged, and reforged to be among the most lethal, merciless, and obedient warriors in the multiverse. While rank-and-file horned devils are called cornugons, the greatest of their kind are known as malebranche.\n\nA typical horned devil rises to a hulking 9 ft. tall, bears 14-foot-wide wings, and weighs 700 pounds.","ecology":"","habitat_society":""},{"name":"Juggerloathe","cr":16,"xp":76800,"alignment":"CE","size":"Gargantuan","type":"magical beast","init":5,"senses":[{"type":"darkvision","modifier":"120 ft."},{"type":"low-light vision"},{"type":"scent"},{"type":"tremorsense","modifier":"120 ft."}],"ac":32,"ac_touch":7,"ac_flat_footed":31,"ac_mods":"+1 Dex, +25 natural, -4 size","hp":256,"hd":"19d10+152","hdvalue":19,"fort":19,"ref":14,"will":12,"dr":"10/adamantine","sr":22,"speed":[{"type":"land","speed":40},{"type":"burrow","speed":30}],"melee":"2 bites +26 (3d8+11), 2 claws +26 (2d8+11)","space":"20 ft.","reach":"20 ft.","special_attacks":[{"type":"devour life"},{"type":"ejection"},{"type":"leaping shockwave"},{"type":"swallow whole","details":"AC 23, hp 30"},{"type":"trample","details":"2d8+11, DC 30"}],"strength":32,"dexterity":13,"constitution":26,"intelligence":5,"wisdom":19,"charisma":12,"baseatk":19,"cmb":34,"cmb_special":"+2 vs. bull rush","cmd":45,"cmd_special":"+2 vs. bull rush, +4 vs. trip","feats":[{"feat":"Improved Bull Rush"},{"feat":"Improved Initiative"},{"feat":"Improved Iron Will"},{"feat":"Iron Will"},{"feat":"Lightning Reflexes"},{"feat":"Lunge"},{"feat":"Power Attack"},{"feat":"Run"},{"feat":"Skill Focus (Perception)"},{"feat":"Snatch"}],"skills":[{"skill":"Acrobatics","value":17},{"skill":"Perception","value":16}],"languages":["Orc"],"environments":["any (Hold of Belkzen)"],"organizations":["unique"],"treasure":"double","description_visual":"This massive spiked creature has smoking black pits for eyes, an enormous maw, and a tail that appears to be an armored cobra.","source":"Belkzen Hold Of The Orc Hordes","special_abilities":[{"type":"Devour Life","kind":"Su","details":"The Juggerloathe's stomach leeches the life force of those trapped within it, rather than digesting them with acids. Any living victims that are swallowed whole and killed while within the Juggerloathe are turned into twisted creatures of undeath and pain. Regardless of their original size or form, those killed within the Juggerloathe become bodaks, though their appearance may be less humanoid than those of typical bodaks. These undead stop taking damage while within the Juggerloathe, and escape its innards when it next uses its ejection attack. The undead aren't controlled by the Juggerloathe, but they don't attack it and it is immune to their powers."},{"type":"Ejection","kind":"Ex","details":"The Juggerloathe can eject the contents of its stomach in a 60-foot cone that deals 8d6 points of acid damage (Reflex DC 27 half) once every 1d6 rounds. Any creatures swallowed whole by it-still living and undead-land prone at the far end of the cone. The save DC is Constitution-based."},{"type":"Leaping Shockwave","kind":"Ex","details":"The Juggerloathe leaps into combat much like normal bulettes, but lands with an earth-shaking impact. When it charges, it can attempt a DC 25 Acrobatics check to jump into the air and land next to its enemies. If it's successful, all adjacent foes must succeed at a DC 30 Reflex save or be knocked prone. The Juggerloathe ends its charge with two bite attacks and two claw attacks, dividing them up as it sees fit among targets within reach. The save DC is Strength-based."}],"description":"The seemingly unstoppable spawn of a bulette of massive size and Yethazmari, the Juggerloathe is 50 ft. from its nose to the base of its tail, and weighs slightly more than 100 tons. It has been a living legend among the tribes of Belkzen for centuries. Although it's seemingly content to remain hidden in its lair within the Mindspin Mountains, the creature is sometimes driven out onto the plains by hunger. Entire tribes have been known to disappear into its gullet, and it leaves only desolation and fiendishly warped undead in the wake of its rampages.","ecology":"","habitat_society":""},{"name":"Labyrinth Minotaur","cr":16,"xp":76800,"alignment":"CE","size":"Large","type":"outsider","subtypes":["chaotic","evil","extraplanar"],"init":4,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":29,"ac_touch":13,"ac_flat_footed":29,"ac_mods":"+4 Dex, +16 natural, -1 size","hp":232,"hd":"15d10+150","hdvalue":15,"fort":19,"ref":9,"will":17,"defensive_abilities":["natural cunning"],"resists":[{"type":"fire","value":20}],"speed":[{"type":"land","speed":30}],"melee":"+1 greataxe +26 (3d6+17/19-20/x3), gore +20 (1d8+5) or gore +25 (1d8+16)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"bronze mask"},{"type":"powerful charge","details":"gore, 2d8+16"},{"type":"steel-shod hooves"},{"type":"trample","details":"2d6+16, DC 28"}],"strength":33,"dexterity":19,"constitution":30,"intelligence":17,"wisdom":26,"charisma":14,"baseatk":15,"cmb":27,"cmb_special":"+4 vs. bull rush","cmd":41,"cmd_special":"+2 vs. bull rush","feats":[{"feat":"Awesome Blow"},{"feat":"Cleave"},{"feat":"Greater Bull Rush"},{"feat":"Improved Bull Rush"},{"feat":"Improved Critical (greataxe)"},{"feat":"Intimidating Prowess"},{"feat":"Power Attack"},{"feat":"Quick Bull Rush"}],"skills":[{"skill":"Climb","value":24},{"skill":"Craft (armor)","value":21},{"skill":"Craft (weapons)","value":21},{"skill":"Heal","value":18},{"skill":"Intimidate","value":31},{"skill":"Knowledge (engineering)","value":21},{"skill":"Knowledge (planes)","value":21},{"skill":"Perception","value":26},{"skill":"Sense Motive","value":26},{"skill":"Survival","value":21}],"languages":["Abyssal","Common","Giant"],"sq":[{"type":"compression"}],"environments":["any (Ivory Labyrinth)"],"organizations":["solitary","pair","gang (3-6)"],"treasure":"standard (+1 greataxe)","description_visual":"This hulking minotaur's hooves are clad in imposing steel. The massive beast wears a heavy bronze mask that covers most of its face.","source":"AP 77","special_abilities":[{"type":"Bronze Mask","kind":"Su","details":"A labyrinth minotaur draws agility and ferocity from its bronze mask. When it makes a full-attack action, a labyrinth minotaur wearing its bronze mask can give up its regular attacks and instead make one gore attack or bull rush against each opponent within reach. It must make a separate attack roll against each opponent, and it can't choose to move with targets that are pushed back. A labyrinth minotaur's bronze mask has 40 hit points, hardness 20, and a break DC of 40. If a labyrinth minotaur's bronze mask is stolen or destroyed, it can create a replacement with 1 week of work."},{"type":"Natural Cunning","kind":"Ex","details":"Like a normal minotaur, a labyrinth minotaur possesses innate cunning and logical ability, granting it immunity to maze spells and preventing it from ever becoming lost. Further, a labyrinth minotaur is never caught flat-footed."},{"type":"Steel-Shod Hooves","kind":"Ex","details":"A labyrinth minotaur's steel-shod hooves are particularly devastating when used to trample an opponent. A creature that takes full damage from a labyrinth minotaur's trample ability (because the creature either failed its Reflex save or chose to take an attack of opportunity instead of attempting a Reflex save) is knocked prone and is staggered for 1d4 rounds. A successful Fortitude save (DC equal to that of the labyrinth minotaur's trample ability) reduces the duration of the staggered condition to 1 round."}],"description":"Labyrinth minotaurs are the elite guards and favored servitors of Baphomet. They are thicker and taller than mortal minotaurs, and possess skill in metalcraft that they use to forge armor, weapons, and their personalized and iconic bronze masks. Labyrinth minotaurs eagerly charge intruders, trampling smaller opponents and knocking back larger foes. As they are perceptive, tireless, and incapable of becoming lost, labyrinth minotaurs make excellent guardians of Baphomet's bewildering maze of a domain, the Ivory Labyrinth. Labyrinth minotaurs stand about 11 ft. tall and weigh 1,200 pounds.\n\nEcology\n\nLabyrinth minotaurs resemble their mortal counterparts, as each has the form of a massive, burly humanoid with thick fur on the chest and legs and a horned, bovine head. The hairless skin of a labyrinth minotaur's head is thin and stretched so tightly over the bone that the beast appears to have just a skull atop its neck. This tight skin makes the creature's sharp eyes bulge from their sockets.\n\nUnlike mortal minotaurs, labyrinth minotaurs have no need to eat or sleep and consider the need for either activity a weakness. Labyrinth minotaurs don't age as mortal creatures do; over the centuries of their existence as guardians and enforcers, they instead accumulate masses of battle scars, which they wear with arrogant pride.\n\nLabyrinth minotaurs speak little, but make a lot of noise. They breathe in great snorts, bang their weapons against their armor, and stomp their steel-shod hooves on the ground as they walk. Labyrinth minotaurs seethe with anger and energy, constantly moving about and shifting from hoof to hoof when required to stand in place for more than a few minutes. A labyrinth minotaur prefers to range throughout the narrow, turning corridors of its maze-like hunting grounds, even into dead ends and back, searching for hints of intruders upon which it can vent its bestial fury.\n\nHabitat & Society\n\nThe first minotaurs were created by Lamashtu, and the first and greatest of these creations was none other than Baphomet. These minotaurs came into existence on Golarion in the vast mazes beneath Iblydos. After becoming a demon lord, Baphomet collected the souls of these primal minotaurs and forged them into the labyrinth minotaurs, paragons of their kind and Baphomet's favored servants. The labyrinth minotaurs constantly patrol the twisting pathways of the Ivory Labyrinth to enforce Baphomet's will on lesser denizens of the domain (such as mortal minotaurs and cultists) and to challenge intruders.\n\nLabyrinth minotaurs are as bestial as their mortal kin and prone to outbursts of violent rage, but their high status in Baphomet's service makes them haughty and given to boasting. They feel contemptuous disdain for all mortal creatures but are particularly derisive of mortal creatures lost or confounded by mazes. Like mortal minotaurs, labyrinth minotaurs are perfectly at home in mazes of any kind and are incapable of becoming lost. This affinity for mazes applies to their thinking as well-despite their brutish demeanors, labyrinth minotaurs are good with puzzles and are keen tactical thinkers. When labyrinth minotaurs meet in peace, they sometimes exchange inscrutable riddles or short descriptive puzzles (such as, \"How would you drink a drop of blood inside a severed eyeball while it's in an iron coffer sunk to the bottom of a well without getting wet or being seen by the eye?\").\n\nLabyrinth minotaurs prefer gear and armor made of bronze and steel, as few other materials are sufficiently sturdy for them to use over a long period of time. In addition to their steel shoes, heavy armor, and massive greataxes, all labyrinth minotaurs wear heavy bronze masks. Each labyrinth minotaur makes its own mask, and some spend weeks or even months obsessively shaping and reshaping the bronze over hot forges. At first glance, each of these bronze masks might seem superficially similar, but upon closer inspection a viewer can clearly see the subtle embellishments built in by the individual labyrinth minotaur. These flourishes communicate the minotaur's status and history to other servants of Baphomet. A labyrinth minotaur often adds an embellishment to its mask when it accomplishes an important task on Baphomet's behalf or kills a particularly powerful intruder. A labyrinth minotaur's obsession makes its mask more than mere ornamentation—each is mystically connected to its mask.\n\nLabyrinth minotaurs prefer to patrol alone or in small gangs. They maintain a central communal headquarters that's usually crewed by about six members, with the fiercest labyrinth minotaur commanding the others through bullying and intimidation. This headquarters is concealed deep within a maze and serves as a safe storage area, a locus for discussing strategy, and the site of the gang's forge and metalworking tools.\n\nWhen labyrinth minotaurs meet others of their kind while out patrolling a maze, they usually share a short exchange of riddles or boasts. Occasionally, labyrinth minotaurs recognize each other as being on opposite sides of sprawling, ancient rivalries. In such cases, the first labyrinth minotaur to recognize the other as an enemy surges forward with murderous fury, hoping to catch its rival off guard. Large congregations of labyrinth minotaurs are rare-even when large groups don't engage in these feuds, labyrinth minotaurs fall into divisive boasting that frequently erupts into bloodshed anyway.\n\nLabyrinth minotaurs are rarely encountered outside of the Ivory Labyrinth, and therefore have little interaction with other races beyond visitors to their master's realm. Labyrinth minotaurs display grudging respect for glabrezu and vilsteth demons and undisguised contempt for mortal minotaurs and cultists of Baphomet. Their arrogance precludes true camaraderie with anyone other than those of their own kind.","ecology":"Labyrinth minotaurs resemble their mortal counterparts, as each has the form of a massive, burly humanoid with thick fur on the chest and legs and a horned, bovine head. The hairless skin of a labyrinth minotaur's head is thin and stretched so tightly over the bone that the beast appears to have just a skull atop its neck. This tight skin makes the creature's sharp eyes bulge from their sockets.\n\nUnlike mortal minotaurs, labyrinth minotaurs have no need to eat or sleep and consider the need for either activity a weakness. Labyrinth minotaurs don't age as mortal creatures do; over the centuries of their existence as guardians and enforcers, they instead accumulate masses of battle scars, which they wear with arrogant pride.\n\nLabyrinth minotaurs speak little, but make a lot of noise. They breathe in great snorts, bang their weapons against their armor, and stomp their steel-shod hooves on the ground as they walk. Labyrinth minotaurs seethe with anger and energy, constantly moving about and shifting from hoof to hoof when required to stand in place for more than a few minutes. A labyrinth minotaur prefers to range throughout the narrow, turning corridors of its maze-like hunting grounds, even into dead ends and back, searching for hints of intruders upon which it can vent its bestial fury.","habitat_society":"The first minotaurs were created by Lamashtu, and the first and greatest of these creations was none other than Baphomet. These minotaurs came into existence on Golarion in the vast mazes beneath Iblydos. After becoming a demon lord, Baphomet collected the souls of these primal minotaurs and forged them into the labyrinth minotaurs, paragons of their kind and Baphomet's favored servants. The labyrinth minotaurs constantly patrol the twisting pathways of the Ivory Labyrinth to enforce Baphomet's will on lesser denizens of the domain (such as mortal minotaurs and cultists) and to challenge intruders.\n\nLabyrinth minotaurs are as bestial as their mortal kin and prone to outbursts of violent rage, but their high status in Baphomet's service makes them haughty and given to boasting. They feel contemptuous disdain for all mortal creatures but are particularly derisive of mortal creatures lost or confounded by mazes. Like mortal minotaurs, labyrinth minotaurs are perfectly at home in mazes of any kind and are incapable of becoming lost. This affinity for mazes applies to their thinking as well-despite their brutish demeanors, labyrinth minotaurs are good with puzzles and are keen tactical thinkers. When labyrinth minotaurs meet in peace, they sometimes exchange inscrutable riddles or short descriptive puzzles (such as, \"How would you drink a drop of blood inside a severed eyeball while it's in an iron coffer sunk to the bottom of a well without getting wet or being seen by the eye?\").\n\nLabyrinth minotaurs prefer gear and armor made of bronze and steel, as few other materials are sufficiently sturdy for them to use over a long period of time. In addition to their steel shoes, heavy armor, and massive greataxes, all labyrinth minotaurs wear heavy bronze masks. Each labyrinth minotaur makes its own mask, and some spend weeks or even months obsessively shaping and reshaping the bronze over hot forges. At first glance, each of these bronze masks might seem superficially similar, but upon closer inspection a viewer can clearly see the subtle embellishments built in by the individual labyrinth minotaur. These flourishes communicate the minotaur's status and history to other servants of Baphomet. A labyrinth minotaur often adds an embellishment to its mask when it accomplishes an important task on Baphomet's behalf or kills a particularly powerful intruder. A labyrinth minotaur's obsession makes its mask more than mere ornamentation—each is mystically connected to its mask.\n\nLabyrinth minotaurs prefer to patrol alone or in small gangs. They maintain a central communal headquarters that's usually crewed by about six members, with the fiercest labyrinth minotaur commanding the others through bullying and intimidation. This headquarters is concealed deep within a maze and serves as a safe storage area, a locus for discussing strategy, and the site of the gang's forge and metalworking tools.\n\nWhen labyrinth minotaurs meet others of their kind while out patrolling a maze, they usually share a short exchange of riddles or boasts. Occasionally, labyrinth minotaurs recognize each other as being on opposite sides of sprawling, ancient rivalries. In such cases, the first labyrinth minotaur to recognize the other as an enemy surges forward with murderous fury, hoping to catch its rival off guard. Large congregations of labyrinth minotaurs are rare-even when large groups don't engage in these feuds, labyrinth minotaurs fall into divisive boasting that frequently erupts into bloodshed anyway.\n\nLabyrinth minotaurs are rarely encountered outside of the Ivory Labyrinth, and therefore have little interaction with other races beyond visitors to their master's realm. Labyrinth minotaurs display grudging respect for glabrezu and vilsteth demons and undisguised contempt for mortal minotaurs and cultists of Baphomet. Their arrogance precludes true camaraderie with anyone other than those of their own kind."},{"name":"Mature Adult Gold Dragon","cr":16,"xp":76800,"alignment":"LG","size":"Huge","type":"dragon","subtypes":["fire"],"init":0,"senses":[{"type":"dragon senses"}],"auras":["frightful presence (210 ft., DC 25)"],"ac":33,"ac_touch":8,"ac_flat_footed":33,"ac_mods":"+25 natural, -2 size","hp":250,"hd":"20d12+120","hdvalue":20,"fort":18,"ref":12,"will":19,"dr":"10/magic","immunities":["fire","paralysis","sleep"],"sr":27,"weaknesses":["vulnerability to cold"],"speed":[{"type":"land","speed":60},{"type":"fly","speed":250,"maneuverability":"poor"},{"type":"swim","speed":60}],"melee":"bite +29 (2d8+16/19-20), 2 claws +29 (2d6+11/19-20), tail slap +27 (2d6+16), 2 wings +27 (1d8+5)","space":"15 ft.","reach":"10 ft. (15 ft. with bite)","special_attacks":[{"type":"breath weapon","details":"50-ft. cone, 14d10 fire, DC 26"},{"type":"crush","details":"2d8+16, DC 26"},{"type":"weakening breath"}],"spell_like_abilities_caster_level":20,"spell_like_abilities_concentration":26,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"bless"},{"spell":"daylight"},{"spell":"detect evil"}]}],"spellsknown_caster_level":9,"spellsknown_concentration":15,"spellsknown":[{"spell_level":4,"spell_slots":5,"spells":[{"spell":"divination"},{"spell":"restoration"}]},{"spell_level":3,"spell_slots":7,"spells":[{"spell":"dispel magic"},{"spell":"invisibility purge"},{"spell":"prayer"}]},{"spell_level":2,"spell_slots":7,"spells":[{"spell":"aid"},{"spell":"cure moderate wounds"},{"spell":"lesser restoration"},{"spell":"resist energy"}]},{"spell_level":1,"spell_slots":8,"spells":[{"spell":"alarm"},{"spell":"divine favor"},{"spell":"mage armor"},{"spell":"shield"},{"spell":"shield of faith"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"detect magic"},{"spell":"light"},{"spell":"mage hand"},{"spell":"mending"},{"spell":"open/close"},{"spell":"prestidigitation"},{"spell":"read magic"},{"spell":"stabilize"}]}],"strength":33,"dexterity":10,"constitution":23,"intelligence":20,"wisdom":21,"charisma":20,"baseatk":20,"cmb":33,"cmd":43,"cmd_special":"+4 vs. trip","feats":[{"feat":"Alertness"},{"feat":"Critical Focus"},{"feat":"Extend Spell"},{"feat":"Improved Critical (bite, claw)"},{"feat":"Iron Will"},{"feat":"Multiattack"},{"feat":"Power Attack"},{"feat":"Stunning Critical"},{"feat":"Vital Strike"}],"skills":[{"skill":"Diplomacy","value":28},{"skill":"Fly","value":15},{"skill":"Heal","value":28},{"skill":"Knowledge (arcana)","value":28},{"skill":"Knowledge (local)","value":28},{"skill":"Knowledge (nobility)","value":28},{"skill":"Knowledge (religion)","value":28},{"skill":"Perception","value":32},{"skill":"Sense Motive","value":32},{"skill":"Spellcraft","value":28},{"skill":"Swim","value":42}],"languages":["Celestial","Common","Draconic","Elven","Halfling","1 more"],"sq":[{"type":"change shape"},{"type":"detect gems"},{"type":"fast flight"},{"type":"luck"}],"environments":["warm plains"],"organizations":["solitary"],"treasure":"triple","description_visual":"Golden scales cover the body of this majestic dragon, and a regal crest of horns arches backward above wise and piercing eyes.","group":"Metallic Dragon","source":"PFRPG Bestiary","special_abilities":[{"type":"Change Shape","kind":"Su","details":"A very young or older gold dragon can assume any animal or humanoid form three times per day as if using polymorph."},{"type":"Detect Gems","kind":"Sp","details":"A young or older gold dragon can detect gems three times per day. This functions as locate object, but can only be used to locate gemstones."},{"type":"Fast Flight","kind":"Ex","details":"A young or older gold dragon is treated as one size category larger when determining his fly speed."},{"type":"Luck","kind":"Sp","details":"Once per day an adult or older gold dragon can touch a gem, usually one embedded in the dragon's hide, and enspell it to bring good luck. As long as the dragon carries the gem, it and every good creature within a given radius of it (10 ft. per age category) receives a +1 luck bonus on all saving throws. If the dragon gives an enspelled gem to another creature, only that bearer gets the bonus. The effect lasts 1d3 hours plus 3 hours per age category of the dragon. This ability is the equivalent of a 2nd-level spell."},{"type":"Weakening Breath","kind":"Su","details":"Instead of a cone of fire, a gold dragon can breathe a cone of weakening gas. Creatures within the cone must succeed on a Fortitude save or take 1 point of Strength damage per age category (Will save half)."}],"description":"Gold dragons are the epitome of virtue. Other metallic dragons revere their gold cousins as the agents of divine forces and the paragons of dragonkind, and often seek them for advice or aid.","ecology":"","habitat_society":""},{"name":"Mithral Golem","cr":16,"xp":76800,"alignment":"N","size":"Huge","type":"construct","init":7,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":32,"ac_touch":16,"ac_flat_footed":24,"ac_mods":"+7 Dex, +1 dodge, +16 natural, -2 size","hp":172,"hd":"24d10+40","hdvalue":24,"fort":8,"ref":15,"will":8,"dr":"15/adamantine, evasion","immunities":["construct traits","magic"],"speed":[{"type":"land","speed":50}],"melee":"2 slams +33 (4d10+11)","space":"15 ft.","reach":"15 ft.","special_attacks":[{"type":"fluid form"},{"type":"quickness"}],"strength":33,"dexterity":24,"wisdom":11,"charisma":1,"baseatk":24,"cmb":37,"cmd":55,"feats":[{"feat":"Dodge","type":"bonus"},{"feat":"Mobility","type":"bonus"},{"feat":"Run","type":"bonus"},{"feat":"Spring Attack","type":"bonus"}],"environments":["any"],"organizations":["solitary","gang (2-4)"],"treasure":"none","description_visual":"Made of polished silvery metal, this immense humanoid construct moves with shocking grace and speed.","group":"Golem","source":"PFRPG Bestiary 2","special_abilities":[{"type":"Fluid Form","kind":"Ex","details":"A mithral golem's body can take on a form like liquid silver as a swift action. While in this form, the mithral golem's reach increases to 30 ft. and its DR becomes 15/bludgeoning and adamantine. A mithral golem in this form can also move through any crack or hole in a wall or door, no matter how small, without impeding its movement. A mithral golem can maintain this form for up to 10 rounds per day, but these rounds don't need to be consecutive. Reverting to its normal form is a free action."},{"type":"Immunity to Magic","kind":"Ex","details":"A mithral golem is immune to any spell or spell-like ability that allows spell resistance. In addition, certain spells and effects function differently against a mithral golem, as noted below. • A slow spell cast on the golem causes it to lose its quickness ability for 1d6 rounds. • A haste spell heals the golem of 1d6 points of damage per level of the caster (maximum 10d6). • Hitting a mithral golem in fluid form with any spell of 6th level or higher with the cold descriptor causes the golem to take 10d6 points of damage (no save) and lose the use of its fluid form ability for 24 hours."},{"type":"Quickness","kind":"Ex","details":"A mithral golem is incredibly quick. It can take an extra move action during its turn each round. This means it can move up to its speed and still make a full attack."}],"description":"Created from a massive quantity of the purest mithral, this golem is a thing of shining beauty. Unlike most golems, mithral golems are extremely agile, capable of moving at great speed and striking swiftly.\n\nConstruction\n\nA mithral golem's body is made of 3,000 pounds of mithral and other precious metals, worth a total of 50,000 gp.\n\nMITHRAL GOLEM\n\nCL 18th; Price 250,000 gp\n\nConstruction\n\nRequirements Craft Construct, animate objects, geas/quest, haste, polymorph any object, wish, creator must be caster level 18th; Skill Craft (sculpture) DC 25; Cost 150,000 gp","ecology":"","habitat_society":""},{"name":"Mythic Ice Devil","cr":16,"xp":76800,"alignment":"LE","size":"Large","type":"outsider","subtypes":["devil","evil","extraplanar","lawful","mythic"],"init":15,"init_special":"mythic","senses":[{"type":"all-around vision"},{"type":"darkvision","modifier":"60 ft."},{"type":"see in darkness"}],"auras":["fear (10 ft., DC 24)"],"ac":38,"ac_touch":14,"ac_flat_footed":33,"ac_mods":"+5 Dex, +24 natural, -1 size","hp":221,"hd":"14d10+144","hdvalue":14,"hp_mods":["regeneration 5 (good spells, good weapons)"],"fort":15,"ref":14,"will":12,"defensive_abilities":["cold logic"],"dr":"10/epic and good","immunities":["cold","fire","poison"],"resists":[{"type":"acid","value":10}],"sr":27,"speed":[{"type":"land","speed":40},{"type":"fly","speed":60,"maneuverability":"good"}],"speed_mod":"ice burrowing 30 ft.","melee":"+2 frost spear +23 (2d6+12/x3 plus 1d6 cold plus ice shards plus slow), bite +15 (2d6+3), tail slap +15 (1d8+3 plus slow)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"entrap","details":"DC 23, 1d10 rounds, hardness 5, hp 10"},{"type":"favored enemy","details":"+6"},{"type":"mythic power","details":"6/day, surge +1d8"},{"type":"pounce"}],"spell_like_abilities_caster_level":13,"spell_like_abilities_concentration":19,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"fly"}]},{"frequency":"at-will","spells":[{"spell":"cone of cold"},{"spell":"greater teleport","details":"self plus 50 lbs. of objects only"},{"spell":"ice storm"},{"spell":"persistent image"},{"spell":"wall of ice"}]},{"frequency":"1/day","spells":[{"spell":"summon","details":"level 4, 2 bone devils 50%"}]}],"strength":25,"dexterity":21,"constitution":22,"intelligence":25,"wisdom":22,"charisma":24,"baseatk":14,"cmb":22,"cmd":37,"feats":[{"feat":"Alertness"},{"feat":"Cleave"},{"feat":"Combat Reflexes","type":"mythic"},{"feat":"Improved Initiative","type":"mythic"},{"feat":"Iron Will","type":"mythic"},{"feat":"Power Attack"},{"feat":"Weapon Focus (spear)"}],"skills":[{"skill":"Acrobatics","value":22},{"skill":"Bluff","value":24},{"skill":"Diplomacy","value":24},{"skill":"Fly","value":13},{"skill":"Intimidate","value":21},{"skill":"Knowledge (planes)","value":24},{"skill":"Knowledge (any three others)","value":21},{"skill":"Perception","value":27},{"skill":"Sense Motive","value":27},{"skill":"Spellcraft","value":21},{"skill":"Stealth","value":18},{"skill":"Survival","value":23}],"languages":["Celestial","Common","Draconic","Infernal","telepathy 100 ft."],"environments":["any (Hell)"],"organizations":["solitary","team (2-3)","council (4-10)","contingent (1-3 ice devils, 2-6 horned devils, and 1-4 bone devils)"],"treasure":"standard (+2 frost spear)","description_visual":"Frozen barbs cover the almost skeletal form of this mantis-like creature, and its icy eyes shine with fiendish intelligence.","group":"Devil","source":"Mythic Adventures","special_abilities":[{"type":"Cold Logic","kind":"Su","details":"When a mythic ice devil's spell resistance protects it from a mind-affecting effect, it can expend one use of mythic power as an immediate action to turn that effect upon its source, as if using spell turning."},{"type":"Favored Enemy","kind":"Ex","details":"A mythic ice devil can expend one use of mythic power to gain a +6 favored enemy bonus against one type of creature for 1 hour, as if it were a 14th-level ranger."},{"type":"Ice Burrowing","kind":"Ex","details":"This ability works like the burrow ability, but only through ice and snow (including magical ice such as a wall of ice)."},{"type":"Ice Shards","kind":"Su","details":"A mythic ice devil's ice-tipped spear embeds jagged shards of supernaturally cold ice in its target. This functions as bleed (1d6), except the damage is cold damage. Dealing 5 or more points of fire damage to the target removes all ice shards. Creatures with the fire subtype are immune to this ability."},{"type":"Slow","kind":"Su","details":"A hit from a mythic ice devil's tail or spear induces numbing cold. The opponent must succeed at a DC 23 Fortitude save or be affected as though by a slow spell for 1d6 rounds. This effect comes from the devil, not its weapon; it isn't a quality possessed by the spear itself. The save DC is Constitution-based."}],"description":"A mythic ice devil is a master of strategy, able to adapt to the nature of its opponents and turn its enemy's attacks back at them. Its lean form and upright posture sets it apart from the stockier non-mythic ice devils.","ecology":"","habitat_society":""},{"name":"Nightwalker","cr":16,"xp":76800,"alignment":"CE","size":"Huge","type":"undead","subtypes":["extraplanar","nightshade"],"init":2,"senses":[{"type":"darksense"},{"type":"darkvision","modifier":"60 ft."},{"type":"detect magic"},{"type":"low-light vision"}],"auras":["desecrating aura (30 ft.)"],"ac":31,"ac_touch":10,"ac_flat_footed":29,"ac_mods":"+2 Dex, +21 natural, -2 size","hp":241,"hd":"21d8+147","hdvalue":21,"fort":14,"ref":11,"will":19,"dr":"15/good and silver","immunities":["cold","undead traits"],"sr":27,"weaknesses":["light aversion"],"speed":[{"type":"land","speed":40}],"melee":"2 claws +28 (3d6+15/19-20 plus 4d6 cold)","space":"15 ft.","reach":"15 ft.","special_attacks":[{"type":"channel energy","details":"8d6, DC 29, 8/day"},{"type":"fear gaze"},{"type":"swift sundering"}],"spell_like_abilities_caster_level":16,"spell_like_abilities_concentration":16,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"air walk"},{"spell":"detect magic"},{"spell":"magic fang"}]},{"frequency":"at-will","spells":[{"spell":"contagion"},{"spell":"deeper darkness"},{"spell":"greater dispel magic"},{"spell":"unholy blight"}]},{"frequency":"1/day","spells":[{"spell":"cone of cold"},{"spell":"finger of death"},{"spell":"plane shift"},{"spell":"summon","details":"level 7, 4 greater shadows"}]},{"frequency":"3/day","spells":[{"spell":"confusion"},{"spell":"haste"},{"spell":"hold monster"},{"spell":"invisibility"},{"spell":"quickened unholy blight"}]}],"strength":35,"dexterity":14,"intelligence":20,"wisdom":21,"charisma":21,"baseatk":15,"cmb":29,"cmd":41,"feats":[{"feat":"Combat Expertise"},{"feat":"Command Undead"},{"feat":"Greater Sunder"},{"feat":"Greater Vital Strike"},{"feat":"Improved Critical (claws)"},{"feat":"Improved Disarm"},{"feat":"Improved Sunder"},{"feat":"Improved Vital Strike"},{"feat":"Power Attack"},{"feat":"Quicken Spell-Like Ability (unholy blight)"},{"feat":"Vital Strike"}],"skills":[{"skill":"Intimidate","value":29},{"skill":"Knowledge (arcana)","value":29},{"skill":"Knowledge (planes)","value":26},{"skill":"Knowledge (religion)","value":29},{"skill":"Perception","value":29},{"skill":"Sense Motive","value":29},{"skill":"Spellcraft","value":29},{"skill":"Stealth","value":18,"special":"+26 in darkness"},{"skill":"Swim","value":33}],"languages":["Abyssal","Common","Infernal","telepathy 100 ft."],"environments":["any (Negative Energy Plane)"],"organizations":["solitary","pair","gang (3-4)"],"treasure":"standard","description_visual":"This towering, night-black giant has demonic features, including a huge pair of ram-like horns. Its arms end in massive blades.","group":"Nightshade","source":"PFRPG Bestiary 2","special_abilities":[{"type":"Fear Gaze","kind":"Su","details":"Cower in fear for 1 round, 30 ft., Will DC 25 negates. This is a mind-affecting fear effect. The save DC is Charisma-based."},{"type":"Swift Sundering","kind":"Su","details":"A nightwalker can make a sunder attempt as a swift action with one of its claws."}],"description":"The most commonly encountered nightshade is the giant-like nightwalker. This powerful foe leads armies of undead against the living, but unlike most mortal generals the nightwalker isn't content to stand back and observe the battles from safety. The undead creature is ever eager to put its tactics and plans to the test itself, and takes part in battles in every possible occurrence save for those that the creature has determined are self-destructive. This isn't to say that the nightwalker never sacrifices its troops to gain a tactical advantage-just that these attacks are the only ones the monster feels no urge to participate in directly.\n\nNightwalkers enjoy inf licting despair before death, particularly by destroying valued objects or murdering loved ones before delivering the final blow to a foe.\n\nA nightwalker is 20 ft. tall and weighs 5,000 pounds.","ecology":"","habitat_society":""},{"name":"Old Blue Dragon","cr":16,"xp":76800,"alignment":"LE","size":"Gargantuan","type":"dragon","subtypes":["earth"],"init":3,"senses":[{"type":"dragon senses"}],"auras":["electricity (10 ft., 1d6 electricity)","frightful presence (240 ft., DC 24)"],"ac":31,"ac_touch":5,"ac_flat_footed":31,"ac_mods":"-1 Dex, +26 natural, -4 size","hp":250,"hd":"20d12+120","hdvalue":20,"fort":18,"ref":11,"will":16,"dr":"10/magic","immunities":["electricity","paralysis","sleep"],"sr":27,"speed":[{"type":"land","speed":40},{"type":"burrow","speed":20},{"type":"fly","speed":250,"maneuverability":"clumsy"}],"melee":"bite +27 (4d6+15/19-20), 2 claws +26 (2d8+10), 2 wings +24 (2d6+5), tail slap +24 (2d8+15)","space":"20 ft.","reach":"15 ft. (20 ft. with bite)","special_attacks":[{"type":"breath weapon","details":"120-ft. line, DC 26, 16d8 electricity"},{"type":"crush","details":"Medium creatures, DC 26, 4d6+15"},{"type":"desert thirst","details":"DC 26"},{"type":"mirage"},{"type":"tail sweep","details":"Small creatures, DC 26, 2d6+15"}],"spell_like_abilities_caster_level":20,"spell_like_abilities_concentration":30,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"ghost sound"},{"spell":"hallucinatory terrain"},{"spell":"minor image"},{"spell":"ventriloquism"}]}],"spellsknown_caster_level":9,"spellsknown_concentration":19,"spellsknown":[{"spell_level":4,"spell_slots":5,"spells":[{"spell":"dimension door"},{"spell":"enervation"}]},{"spell_level":3,"spell_slots":7,"spells":[{"spell":"dispel magic"},{"spell":"haste"},{"spell":"vampiric touch"}]},{"spell_level":2,"spell_slots":7,"spells":[{"spell":"darkness"},{"spell":"invisibility"},{"spell":"resist energy"},{"spell":"shatter"}]},{"spell_level":1,"spell_slots":7,"spells":[{"spell":"alarm"},{"spell":"mage armor"},{"spell":"shield"},{"spell":"true strike"},{"spell":"unseen servant"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"arcane mark"},{"spell":"bleed"},{"spell":"detect magic"},{"spell":"light"},{"spell":"mage hand"},{"spell":"mending"},{"spell":"read magic"},{"spell":"resistance"}]}],"strength":31,"dexterity":8,"constitution":23,"intelligence":18,"wisdom":19,"charisma":18,"baseatk":20,"cmb":34,"cmd":43,"cmd_special":"+4 vs. trip","feats":[{"feat":"Combat Casting"},{"feat":"Dazzling Display"},{"feat":"Deadly Stroke"},{"feat":"Extend Spell"},{"feat":"Hover"},{"feat":"Improved Critical (bite)"},{"feat":"Improved Initiative"},{"feat":"Multiattack"},{"feat":"Shatter Defenses"},{"feat":"Weapon Focus (bite)"}],"skills":[{"skill":"Bluff","value":27},{"skill":"Fly","value":8},{"skill":"Intimidate","value":27},{"skill":"Knowledge (arcana)","value":27},{"skill":"Knowledge (geography)","value":27},{"skill":"Knowledge (local)","value":27},{"skill":"Perception","value":27},{"skill":"Spellcraft","value":27},{"skill":"Stealth","value":10},{"skill":"Survival","value":27}],"languages":["Auran","Common","Draconic","Giant","Ignan"],"sq":[{"type":"sound imitation"}],"environments":["warm deserts"],"organizations":["solitary"],"treasure":"triple","description_visual":"With scales the color of the desert sky, this large, serpentine dragon moves with an unsettling grace.","group":"Chromatic Dragon","source":"PFRPG Bestiary","special_abilities":[{"type":"Desert Thirst","kind":"Su","details":"A blue dragon can cast create water at will (CL 20). Alternatively, it can destroy an equal amount of liquid in a 10-foot burst. Unattended liquids are instantly reduced to sand. Liquid-based magic items (such as potions) and items in a creature's possession must succeed on a Will save (DC 26) or be destroyed."},{"type":"Electricity Aura","kind":"Su","details":"An old blue dragon is surrounded by an aura of electricity. Creatures within 10 ft. take 1d6 points of electricity damage at the beginning of the dragon's turn."},{"type":"Mirage","kind":"Su","details":"An old blue dragon can make itself appear to be in two places at once as a free action for 20 rounds per day. This ability functions as project image but the dragon can use its breath weapon through the mirage."},{"type":"Sound Imitation","kind":"Ex","details":"A very young or older blue dragon can mimic any voice or sound it has heard by making a successful Bluff check against a listener's Sense Motive check."}],"description":"Blue dragons are consummate schemers and obsessively orderly. In combat, blue dragons prefer to surprise foes if possible, and are not above retreating if the odds turn against them. They prefer to lair near those that they control, sometimes even within the confines of a city.","ecology":"","habitat_society":""},{"name":"Old Bronze Dragon","cr":16,"xp":76800,"alignment":"LG","size":"Gargantuan","type":"dragon","subtypes":["water"],"init":3,"senses":[{"type":"dragon senses"}],"auras":["electricity aura (5 ft.,1d6 electricity)","frightful presence (240 ft., DC 26)"],"ac":31,"ac_touch":5,"ac_flat_footed":31,"ac_mods":"-1 Dex, +26 natural, -4 size","hp":250,"hd":"20d12+120","hdvalue":20,"fort":18,"ref":11,"will":18,"dr":"10/magic","immunities":["electricity","paralysis","sleep"],"sr":27,"speed":[{"type":"land","speed":40},{"type":"fly","speed":250,"maneuverability":"clumsy"},{"type":"swim","speed":60}],"melee":"bite +26 (4d6+15/19-20), 2 claws +26 (2d8+10), tail slap +24 (2d8+15), 2 wings +24 (2d6+5)","space":"20 ft.","reach":"15 ft. (20 ft. with bite)","special_attacks":[{"type":"breath weapon","details":"120-ft. line, DC 26, 16d6 electricity"},{"type":"crush","details":"4d6+15, DC 26"},{"type":"repulsion breath"},{"type":"tail sweep","details":"2d6+15, DC 26"}],"spell_like_abilities_caster_level":20,"spell_like_abilities_concentration":26,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"create food and water"},{"spell":"detect thoughts"},{"spell":"fog cloud"},{"spell":"speak with animals"}]}],"spellsknown_caster":"sorcerer","spellsknown_caster_level":11,"spellsknown_concentration":17,"spellsknown":[{"spell_level":5,"spell_slots":5,"spells":[{"spell":"mind fog"},{"spell":"teleport"}]},{"spell_level":4,"spell_slots":7,"spells":[{"spell":"dimension door"},{"spell":"ice storm"},{"spell":"solid fog"}]},{"spell_level":3,"spell_slots":7,"spells":[{"spell":"dispel magic"},{"spell":"heroism"},{"spell":"slow"},{"spell":"suggestion"}]},{"spell_level":2,"spell_slots":8,"spells":[{"spell":"blur"},{"spell":"gust of wind"},{"spell":"invisibility"},{"spell":"mirror image"},{"spell":"web"}]},{"spell_level":1,"spell_slots":8,"spells":[{"spell":"alarm"},{"spell":"mage armor"},{"spell":"obscuring mist"},{"spell":"shield"},{"spell":"true strike"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"detect magic"},{"spell":"detect poison"},{"spell":"light"},{"spell":"mage hand"},{"spell":"mending"},{"spell":"message"},{"spell":"read magic"},{"spell":"resistance"},{"spell":"prestidigitation"}]}],"strength":31,"dexterity":8,"constitution":23,"intelligence":22,"wisdom":23,"charisma":22,"baseatk":20,"cmb":34,"cmd":43,"cmd_special":"+4 vs. trip","feats":[{"feat":"Alertness"},{"feat":"Cleave"},{"feat":"Flyby Attack"},{"feat":"Hover"},{"feat":"Improved Critical (bite)"},{"feat":"Improved Initiative"},{"feat":"Improved Vital Strike"},{"feat":"Multiattack"},{"feat":"Power Attack"},{"feat":"Vital Strike"}],"skills":[{"skill":"Diplomacy","value":29},{"skill":"Fly","value":8},{"skill":"Handle Animal","value":26},{"skill":"Intimidate","value":29},{"skill":"Knowledge (arcana, geography, history)","value":29},{"skill":"Perception","value":33},{"skill":"Sense Motive","value":33},{"skill":"Spellcraft","value":29},{"skill":"Stealth","value":10},{"skill":"Swim","value":41}],"languages":["Aquan","Common","Draconic","Elven","Gnome","2 more"],"sq":[{"type":"change shape","details":"animal or humanoid, polymorph"},{"type":"water breathing"},{"type":"wave mastery","details":"80 min"}],"environments":["temperate coastlines"],"organizations":["solitary"],"treasure":"triple","description_visual":"This sleek dragon is covered in dull metallic scales that range in color from shining bronze to mottled blue.","group":"Metallic Dragon","source":"PFRPG Bestiary","special_abilities":[{"type":"Electricity Aura","kind":"Su","details":"An old or older bronze dragon has an aura of electricity. All creatures within 5 ft. take 1d6 points of electricity damage at the start of the dragon's turn. An ancient dragon's aura is 10 ft. A great wyrm's damage increases to 2d6. A bronze dragon can suppress this aura at will."},{"type":"Repulsion Breath","kind":"Su","details":"Instead of a line of electricity, a bronze dragon can breathe a cone of repulsion gas. Targets must make a Will save or be compelled to do nothing but move away from the dragon for 1d6 rounds plus 1 round per age category. This is a mind-affecting compulsion effect."},{"type":"Water Breathing","kind":"Ex","details":"A bronze dragon breathes water and can use its breath weapon, spells, and abilities underwater."},{"type":"Wave Mastery","kind":"Su","details":"For up to 10 minutes per age category per day, a juvenile bronze dragon, along with creatures or vessels within 50 ft., can move at twice its normal speed in water."}],"description":"Bronze dragons have been known to ally with travelers and adventurers if the cause and reward is right and just.","ecology":"","habitat_society":""},{"name":"Oma","cr":16,"xp":76800,"alignment":"N","size":"Colossal","type":"magical beast","init":-2,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":30,"ac_touch":0,"ac_flat_footed":30,"ac_mods":"-2 Dex, +30 natural, -8 size","hp":290,"hd":"20d10+180","hdvalue":20,"fort":23,"ref":10,"will":7,"immunities":["cold","electricity","fire"],"speed":[{"type":"fly","speed":200,"maneuverability":"average"}],"melee":"bite +33 (4d6+21 plus 2d6 electricity and grab), tail slap +28 (4d6+10)","space":"30 ft.","reach":"30 ft.","special_attacks":[{"type":"capsize"},{"type":"swallow whole","details":"6d6 acid damage, AC 25, 29 hp"}],"strength":52,"dexterity":7,"constitution":29,"intelligence":2,"wisdom":12,"charisma":5,"baseatk":20,"cmb":49,"cmb_special":"+2 vs. bull rush, +4 vs. grapple","cmd":57,"cmd_special":"+2 vs. bull rush, can't be tripped","feats":[{"feat":"Awesome Blow"},{"feat":"Critical Focus"},{"feat":"Diehard"},{"feat":"Endurance"},{"feat":"Flyby Attack"},{"feat":"Great Fortitude"},{"feat":"Improved Bull Rush"},{"feat":"Power Attack"},{"feat":"Staggering Critical"},{"feat":"Vital Strike"}],"skills":[{"skill":"Fly","value":-10},{"skill":"Perception","value":24}],"sq":[{"type":"carrier"},{"type":"no breath"},{"type":"starflight"}],"environments":["any gas giants","any vacuum"],"organizations":["solitary","pair","pod (3-6)"],"treasure":"incidental","description_visual":"This whale-like creature floats ponderously, arcs of brilliant energy filling its mouth and rolling down its body.","source":"PFRPG Bestiary 4","special_abilities":[{"type":"Capsize","kind":"Ex","details":"An oma can attempt to capsize a ship or other vehicle by ramming it as a charge attack and attempting a combat maneuver check. The DC of this check is 25, or the result of the captain's Profession (sailor) check, whichever is higher. For each size category the ship is larger than the oma, the oma takes a cumulative -10 penalty on this combat maneuver check."},{"type":"Carrier","kind":"Ex","details":"A creature swallowed whole by an oma can forgo attempts to cut itself out and instead attempt a DC 20 Reflex save on its turn. Success allows the creature to move into the creature's larger second stomach, where it can ride safely for an indefinite period without taking damage. When a passenger wishes to leave, it can cut its way free using the normal rules, or attempt an additional DC 20 Reflex save to be safely excreted in a square adjacent to the oma. An oma's carrier stomach can hold up to one Gargantuan creature (or twice as many creatures of the next smallest size: two Huge creatures, four Large, and so on). At its option, an oma can choose to forgo the normal bite damage of swallowing whole, but not the acid damage of the first stomach."},{"type":"Starflight","kind":"Ex","details":"An oma can survive in the void of outer space, and soars through vacuum at incredible speed. Although exact travel times vary, a trip between two planets within a solar system should take 3d20 days, while one to another system should take 3d20 weeks (or more, at the GM's discretion), provided the oma knows the way to its destination."}],"description":"Oma soar through gas giants and the vast gulfs between planets on magical electromagnetic fields, feeding on cosmic materials strained from planetary rings and atmospheres with their energy baleen. Anything ingested by an oma is eventually sequestered in a surprisingly habitable second stomach before being excreted, and some alien creatures use oma as living starships, using telepathy to guide the colossi through the void. A typical oma is 150 ft. long and weighs 250 tons.","ecology":"","habitat_society":""}];
